insert into private.study_guides (guide, chunks, sha256) values ('study_guide_ent211', 34, 'ad1164ae953e2ee51dd5c27dca54573f1523c7105018edf0e777faa197a80e3b');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 1, $study_guide${"guide":"study_guide_ent211","code":"ENT211","courseId":"40000000-0000-4000-8000-000000000001","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"ce24b613-5845-53a2-a748-815347fbc945","before":{"title":"Entrepreneurship and Innovation","body":"Introduction to entrepreneurship and innovation, from recognising opportunities and developing business ideas to funding and launching new ventures, and entrepreneurship's role in economic development.","examFocus":["Definitions of entrepreneurship and innovation","Types of entrepreneurs and their characteristics","Opportunity recognition process","Business idea evaluation","Short essay questions on economic impact","Theoretical frameworks and concepts"]},"after":{"title":"Entrepreneurship and Innovation","body":"Introduction to entrepreneurship and innovation, from recognising opportunities and developing business ideas to funding and launching new ventures, and entrepreneurship's role in economic development.","examFocus":["Definitions of entrepreneurship and innovation","Types of entrepreneurs and their characteristics","Opportunity recognition process","Business idea evaluation","Short essay questions on economic impact","Theoretical frameworks and concepts"],"outcomes":["Define entrepreneurship and describe its scope and dimensions, and the characteristics of an entrepreneur.","Explain the traits of an entrepreneur and whether entrepreneurs are born or made.","Define innovation and its dimensions, link knowledge to innovation, and apply the principles of change management.","Identify the forms of business ownership in Nigeria, weigh their advantages and disadvantages, and outline a simple business plan.","Explain business registration in Nigeria, its process and the pitfalls to avoid, and the forms of business collaboration.","Define and distinguish micro and small enterprises, and explain their importance.","Explain the role of knowledge and skills, digital technology and e-commerce in modern entrepreneurship."],"assessment":["The exam is objective (CBT). Expect definitions, lists and their order, names, figures and Nigerian business cases.","Every topic is examinable."]}},"retire":[{"itemId":"4607037b-1b2e-50e2-b122-8fea3eef480c","revision":1,"parentRevision":null},{"itemId":"a37a3d80-2715-5494-ac2a-783a148cc1e7","revision":1,"parentRevision":null},{"itemId":"d4e9eadd-dd98-533b-8c33-38de22ca0fb9","revision":1,"parentRevision":null},{"itemId":"441233ea-063b-5127-98c1-10203c0f8ac9","revision":1,"parentRevision":null},{"itemId":"b5b488fb-804e-54d6-95ce-642b6369538c","revision":1,"parentRevision":null},{"itemId":"a6d633fa-2929-5af4-a724-600744e683b2","revision":1,"parentRevision":null},{"itemId":"4050d085-07b8-5f9a-8cde-045317562779","revision":1,"parentRevision":null},{"itemId":"51a66624-aad4-5ff0-aacf-15beba765b25","revision":1,"parentRevision":null},{"itemId":"ac0d858e-4aef-5e6e-974d-9f30a23cb7d5","revision":1,"parentRevision":null},{"itemId":"2c8ad9a5-63f6-5be1-a56e-f4c4d4c2e321","revision":1,"parentRevision":null}],"notes":[{"kind":"note","itemId":"e3dec25a-0f96-5212-97c7-3d46b4824851","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Concept of Entrepreneurship","body":"The Aliko Dangote story; the two definitions of entrepreneurship and its simple formula; the nine scopes of entrepreneurship with their examples; the eight characteristics of an entrepreneur; the seven dimensions of entrepreneurship with their examples; the Tunde reflection case.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"The Aliko Dangote story; the two definitions of entrepreneurship and its simple formula; the nine scopes of entrepreneurship with their examples; the eight characteristics of an entrepreneur; the seven dimensions of entrepreneurship with their examples; the Tunde reflection case."}],"lessons":[{"number":"1.1","title":"Learning goals and the Aliko Dangote story","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learning objectives (4):","bold":true},{"text":" by the end of this topic you should be able to:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Define Entrepreneurship."}]},{"text":[{"text":"Describe the Scope and Dimensions of Entrepreneurship."}]},{"text":[{"text":"Understand the Characteristics of an Entrepreneur."}]},{"text":[{"text":"Understand the Dimensions of Entrepreneurship."}]}]}]},{"text":[{"text":"Aliko Dangote's story:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A young man, "},{"text":"21 years old","bold":true},{"text":", from "},{"text":"Kano State","bold":true},{"text":", started a small "},{"text":"trading","bold":true},{"text":" business with a "},{"text":"loan from his uncle","bold":true},{"text":"."}]},{"text":[{"text":"He bought and sold "},{"text":"sugar, rice and cement","bold":true},{"text":", delivering goods "},{"text":"himself","bold":true},{"text":" to customers."}]},{"text":[{"text":"Over time he noticed that "},{"text":"Nigeria imported almost every product it consumed","bold":true},{"text":". He saw a "},{"text":"bigger opportunity","bold":true},{"text":": "},{"text":"produce locally what the country was importing","bold":true},{"text":"."}]},{"text":[{"text":"He took the "},{"text":"bold step","bold":true},{"text":" into "},{"text":"manufacturing","bold":true},{"text":", starting with "},{"text":"cement","bold":true},{"text":"."}]},{"text":[{"text":"Today his companies produce "},{"text":"cement, sugar, salt, pasta, fertilizer and petroleum products","bold":true},{"text":", "},{"text":"creating jobs and transforming industries","bold":true},{"text":" (the Dangote Refinery is one of his plants)."}]}]}]},{"text":[{"text":"Lesson of the story:","bold":true},{"text":" entrepreneurship begins with "},{"text":"spotting opportunities, taking risks and creating value that meets national needs","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 2, $study_guide$ext":"Read the story as a path: small trader (sugar, rice, cement) → spots that Nigeria imports almost everything → moves into manufacturing (cement first) → many products and many jobs. Each step matches an idea you will meet later: spotting the import gap is "},{"text":"opportunity recognition","bold":true},{"text":", moving into manufacturing is "},{"text":"risk taking","bold":true},{"text":", and the jobs and industries he built are "},{"text":"value creation","bold":true},{"text":"."}]},{"text":[{"text":"Exam traps on the numbers and names: age is "},{"text":"21","bold":true},{"text":" (not 18, 25 or 30); state is "},{"text":"Kano","bold":true},{"text":" (not Lagos, Kaduna or Kogi); the money came from an "},{"text":"uncle","bold":true},{"text":" (not a bank, a salary or a government grant)."}]},{"text":[{"text":"Do not mix the two product lists. What he "},{"text":"traded","bold":true},{"text":" at the start: sugar, rice, cement. What his companies "},{"text":"produce","bold":true},{"text":" today: cement, sugar, salt, pasta, fertilizer, petroleum products. Salt, pasta and fertilizer belong to the later list only. Purified bottled water is "},{"text":"not","bold":true},{"text":" a Dangote product; it is Tunde's business in Lesson 1.6."}]},{"text":[{"text":"His first manufacturing product was "},{"text":"cement","bold":true},{"text":", not sugar or fertilizer."}]},{"text":[{"text":"The \"bigger opportunity\" was to "},{"text":"produce locally","bold":true},{"text":" what Nigeria imported. It was not to import more cheaply, export raw produce or open shops for imported goods."}]},{"text":[{"text":"An option that ignores the learning objectives (for example, calculating a break-even point) is not one of the four goals of this topic."}]}]}]},{"number":"1.2","title":"What entrepreneurship means","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Definition 1 (a process):","bold":true},{"text":" entrepreneurship is the process of "},{"text":"identifying opportunities, mobilising resources, creating innovative products or services and taking risks to generate value and achieve profit","bold":true},{"text":"."}]},{"text":[{"text":"Definition 2 (a mindset and process):","bold":true},{"text":" it is the "},{"text":"mindset","bold":true},{"text":" and process of "},{"text":"discovering problems, designing innovative solutions and delivering value","bold":true},{"text":" to "},{"text":"society, markets or organisations","bold":true},{"text":"."}]},{"text":[{"text":"In simple terms:","bold":true},{"text":" "},{"text":"Entrepreneurship = Opportunity + Innovation + Value Creation + Risk","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Definition 1 has four actions and one goal. Actions: identify opportunities, mobilise resources, create innovative products or services, take risks. Goal: "},{"text":"generate value and achieve profit","bold":true},{"text":". If an option says \"delegate all risks to the government\" or \"avoid competition\", it is not part of the definition."}]},{"text":[{"text":"Definition 2 adds the word "},{"text":"mindset","bold":true},{"text":": entrepreneurship is also a way of thinking. Its three steps run in order: discover a problem → design an innovative solution → deliver value. The value goes to "},{"text":"society, markets or organisations","bold":true},{"text":", not just to family, shareholders or government."}]},{"text":[{"text":"The formula has exactly "},{"text":"four","bold":true},{"text":" parts: Opportunity, Innovation, Value Creation, Risk. Common distractors are words from elsewhere in this topic, such as Autonomy, Resource Mobilisation or Profit, or everyday words like Capital, Labour, Money. If asked to complete \"Opportunity + Innovation + ____ + Risk\", the answer is "},{"text":"Value Creation","bold":true},{"text":"."}]},{"text":[{"text":"Think of a Yaba student who sees that classmates waste time queuing to print handouts, sets up a quick printing service, and earns from it. That is opportunity, innovation, value and risk in one small example."}]}]}]},{"number":"1.3","title":"Scope of entrepreneurship","mustKnow":[{"type":"paragraph","text":[{"text":"Entrepreneurship covers "},{"text":"nine","bold":true},{"text":" scopes (areas where it happens):"}]},{"type":"table","header":[[{"text":"Scope"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Technological","bold":true}],[{"text":"Tech-driven solutions"}],[{"text":"Paystack","bold":true},{"text":" and "},{"text":"Flutterwave","bold":true},{"text":" revolutionising digital payments"}]],[[{"text":"Social Entrepreneurship","bold":true}],[{"text":"Innovative solutions to solving social problems"}],[{"text":"Leap Africa","bold":true},{"text":" tackling youth development challenges"}]],[[{"text":"Agricultural","bold":true}],[{"text":"Innovative ideas to agriculture for profit"}],[{"text":"FarmCrowdy","bold":true},{"text":" using crowdfunding for farming"}]],[[{"text":"Educational","bold":true}],[{"text":"Innovation in teaching, learning and educational services"}],[{"text":"uLesson","bold":true}]],[[{"text":"Creative Entrepreneurship","bold":true}],[{"text":"Creativity, talent and cultural expressions to produce value"}],[{"text":"Nollywood","bold":true},{"text":" film, music and fashion brands"}]],[[{"text":"Corporate Entrepreneurship","bold":true}],[{"text":"Innovative activities carried out inside a large organisation to create new products, services or processes"}],[{"text":"MTN MoMo","bold":true},{"text":", "},{"text":"Gmail at Google","bold":true}]],[[{"text":"International Entrepreneurship","bold":true}],[{"text":"Activities across national borders: exporting, expansion and foreign partnership"}],[{"text":"Dangote Cement in 10 African countries","bold":true}]],[[{"text":"Public Sector (Government)","bold":true}],[{"text":"Innovating within public agencies to improve service delivery"}],[{"text":"Digital tax collection systems","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 3, $study_guide$bold":true},{"text":", "},{"text":"online passport application portals","bold":true}]],[[{"text":"Green/Environmental","bold":true}],[{"text":"Developing solutions that protect the environment or promote sustainability"}],[{"text":"Sahara Energy Renewable Project","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learn the first four as a group (Technological, Social, Agricultural, Educational) and the other five as a second group (Creative, Corporate, International, Public Sector, Green/Environmental). Nine in all."}]},{"text":[{"text":"How to tell look-alikes apart:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Corporate","bold":true},{"text":" vs "},{"text":"Public Sector","bold":true},{"text":": both innovate "},{"text":"inside","italic":true},{"text":" an existing body. Corporate is inside a "},{"text":"large organisation","bold":true},{"text":" (MTN, Google, a big bank). Public Sector is inside "},{"text":"government agencies","bold":true},{"text":" to improve service delivery (tax, passports, an online licence-renewal portal)."}]},{"text":[{"text":"Social","bold":true},{"text":" vs "},{"text":"Green/Environmental","bold":true},{"text":": Social solves "},{"text":"social problems","bold":true},{"text":" (Leap Africa and youth development). Green protects the "},{"text":"environment","bold":true},{"text":" or promotes "},{"text":"sustainability","bold":true},{"text":" (Sahara Energy's renewable project; a firm installing solar systems to replace polluting diesel generators)."}]},{"text":[{"text":"Technological","bold":true},{"text":" vs "},{"text":"Corporate","bold":true},{"text":": Paystack and Flutterwave are "},{"text":"technological","bold":true},{"text":" (tech-driven payments). MTN MoMo is also about payments, but it is listed as "},{"text":"corporate","bold":true},{"text":" because it was built inside a large company."}]},{"text":[{"text":"Creative","bold":true},{"text":" covers talent and culture: films, music, fashion. A Lagos musician building a brand around Yoruba culture is creative entrepreneurship."}]},{"text":[{"text":"International","bold":true},{"text":" means crossing borders: exporting, expanding, foreign partnerships. An Aba shoemaker exporting to Ghana and partnering with a distributor in Senegal is international entrepreneurship."}]}]}]},{"text":[{"text":"Number trap: Dangote Cement operates in "},{"text":"10","bold":true},{"text":" African countries (not 5, 15 or 20)."}]},{"text":[{"text":"FarmCrowdy appears twice in this topic: as the example of "},{"text":"Agricultural","bold":true},{"text":" scope (crowdfunding for farming) and as the example of the "},{"text":"Value Creation","bold":true},{"text":" dimension (Lesson 1.5)."}]},{"text":[{"text":"Do not confuse lists. Proactiveness and Autonomy are "},{"text":"dimensions","bold":true},{"text":"; Vision, Resourceful and Risk Taker are "},{"text":"characteristics","bold":true},{"text":". None of them is a scope."}]}]}]},{"number":"1.4","title":"Characteristics of an entrepreneur","mustKnow":[{"type":"paragraph","text":[{"text":"Eight","bold":true},{"text":" characteristics of an entrepreneur:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Vision"}]},{"text":[{"text":"Creativity"}]},{"text":[{"text":"Passion"}]},{"text":[{"text":"Ability to Network"}]},{"text":[{"text":"Self Confidence"}]},{"text":[{"text":"Risk Taker"}]},{"text":[{"text":"Resourceful"}]},{"text":[{"text":"Never Give-up ("},{"text":"Grit","bold":true},{"text":")"}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"These describe the "},{"text":"person","bold":true},{"text":". In plain terms: "},{"text":"vision","bold":true},{"text":" is seeing where you want the business to go; "},{"text":"creativity","bold":true},{"text":" is coming up with new ideas; "},{"text":"passion","bold":true},{"text":" is a deep love for what you do; "},{"text":"ability to network","bold":true},{"text":" is building relationships that bring partners, mentors and customers; "},{"text":"self confidence","bold":true},{"text":" is belief in yourself; "},{"text":"risk taker","bold":true},{"text":" is being willing to step into the unknown; "},{"text":"resourceful","bold":true},{"text":" is making the most of what little you have; "},{"text":"never give-up","bold":true},{"text":" is pushing on after failure."}]},{"text":[{"text":"Grit","bold":true},{"text":" is the other name for "},{"text":"Never Give-up","bold":true},{"text":". Not passion, not vision."}]},{"text":[{"text":"Applying them to stories:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A caterer whose business failed twice but who learned and started again until the third attempt worked: "},{"text":"Never Give-up (Grit)","bold":true},{"text":"."}]},{"text":[{"text":"Someone who attends business events, keeps in touch with mentors and builds relationships that later bring partners and customers: "},{"text":"Ability to Network","bold":true},{"text":"."}]},{"text":[{"text":"Someone with very little money who starts a snack business with her mother's kitchen, second-hand utensils and free social media advertising: "},{"text":"Resourceful","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Count trap: there are "},{"text":"eight","bold":true},{"text":" characteristics (not seven, which is the number of dimensions)."}]},{"text":[{"text":"Look-alike trap: "},{"text":"Risk Taker","bold":true},{"text":" is a characteristic; "},{"text":"Risk taking","bold":true},{"text":" is also a dimension (Lesson 1.5). "},{"text":"Creativity","bold":true},{"text":" is a characteristic; the related dimension is "},{"text":"Innovativeness","bold":true},{"text":". Autonomy, Value Creation, Proactiveness, Opportunity Recognition and Technological are "},{"text":"not","bold":true},{"text":" characteristics."}]}]}]},{"number":"1.5","title":"Dimensions of entrepreneurship","mustKnow":[{"type":"paragraph","$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 4, $study_guide$text":[{"text":"Entrepreneurship has several dimensions that describe the "},{"text":"behaviours, processes and characteristics that drive entrepreneurial activity","bold":true},{"text":". There are "},{"text":"seven","bold":true},{"text":":"}]},{"type":"table","header":[[{"text":"Dimension"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Innovativeness","bold":true}],[{"text":"Creating something new or improving existing products, services or processes"}],[{"text":"Flutterwave","bold":true},{"text":" created an innovative payment infrastructure"}]],[[{"text":"Proactiveness","bold":true}],[{"text":"Entrepreneurs anticipate future trends, act ahead of competitors and seize opportunity early"}],[{"text":"Sim Shagaya","bold":true},{"text":" pioneered "},{"text":"Konga","bold":true},{"text":" (e-commerce) online shopping"}]],[[{"text":"Risk taking","bold":true}],[{"text":"Entrepreneurs take calculated risks in uncertain environments"}],[{"text":"Dangote","bold":true},{"text":" invested in local industries despite import dominance and market uncertainty"}]],[[{"text":"Value Creation","bold":true}],[{"text":"Creating value: economic, social or environmental"}],[{"text":"FarmCrowdy","bold":true},{"text":" connected farmers with digital funding and agricultural support"}]],[[{"text":"Opportunity Recognition","bold":true}],[{"text":"Entrepreneurship begins with identifying unmet needs, market gaps or solutions to problems"}],[{"text":"Flutterwave","bold":true},{"text":"'s innovative payment structure"}]],[[{"text":"Resource Mobilisation","bold":true}],[{"text":"Entrepreneurs know how to gather and manage the resources needed to bring ideas to life"}],[{"text":"Tony Elumelu","bold":true},{"text":" turned "},{"text":"UBA","bold":true},{"text":" into a global bank"}]],[[{"text":"Autonomy","bold":true}],[{"text":"Independence in decision-making and control over their goals and actions"}],[{"text":"Startup founders","bold":true},{"text":" starting enterprises"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In the picture, \"Entrepreneurial Dimensions\" sits at the centre with the seven dimensions around it, showing that all seven work together."}]},{"text":[{"text":"Key words to spot each one in a question:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Creating something new / improving existing\" → "},{"text":"Innovativeness","bold":true},{"text":"."}]},{"text":[{"text":"\"Anticipate trends / ahead of competitors / seize early\" → "},{"text":"Proactiveness","bold":true},{"text":". A startup that predicts cashless payments at roadside markets and launches before any competitor is proactive."}]},{"text":[{"text":"\"Calculated risks / uncertain environments\" → "},{"text":"Risk taking","bold":true},{"text":". Note "},{"text":"calculated","italic":true},{"text":": not reckless, not avoiding all risk, not passing risk to customers."}]},{"text":[{"text":"\"Economic, social or environmental value\" → "},{"text":"Value Creation","bold":true},{"text":". Value is not only economic profit."}]},{"text":[{"text":"\"Unmet needs / market gap\" → "},{"text":"Opportunity Recognition","bold":true},{"text":". A UNILAG student who sees that students struggle to find affordable hostels near campus is recognising an opportunity."}]},{"text":[{"text":"\"Gather and manage resources\" → "},{"text":"Resource Mobilisation","bold":true},{"text":"."}]},{"text":[{"text":"\"Independence / own decisions / control over goals\" → "},{"text":"Autonomy","bold":true},{"text":". Someone who resigns a salaried job to make her own decisions is showing autonomy."}]}]}]},{"text":[{"text":"Example traps: "},{"text":"Flutterwave","bold":true},{"text":" illustrates both "},{"text":"Innovativeness","bold":true},{"text":" and "},{"text":"Opportunity Recognition","bold":true},{"text":". "},{"text":"Sim Shagaya","bold":true},{"text":" pioneered "},{"text":"Konga","bold":true},{"text":" (not Paystack, uLesson or FarmCrowdy), for "},{"text":"Proactiveness","bold":true},{"text":". "},{"text":"Tony Elumelu and UBA","bold":true},{"text":" is "},{"text":"Resource Mobilisation","bold":true},{"text":", not Proactiveness. "},{"text":"Dangote","bold":true},{"text":" here is "},{"text":"Risk taking","bold":true},{"text":". "},{"text":"Startup founders","bold":true},{"text":" is "},{"text":"Autonomy","bold":true},{"text":"."}]},{"text":[{"text":"Do not confuse lists: Passion, Creativity, Vision and Grit are "},{"text":"characteristics","bold":true},{"text":"; Social Entrepreneurship is a "},{"text":"scope","bold":true},{"text":". None is a dimension."}]}]}]},{"number":"1.6","title":"Reflection case: Tunde's water business","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Problem Tunde noticed:","bold":true},{"text":" people in his neighbourhood often struggled to find "},{"text":"clean, affordable drinking water","bold":true},{"text":". Many relied on "},{"text":"bottled water, which was expensive","bold":true},{"text":", or "},{"text":"unsafe local sources","bold":true},{"text":"."}]},{"text":[{"text":"His business:","bold":true},{"text":" producing "},{"text":"purified bottled water","bold":true},{"text":"."}]},{"text":[{"text":"What he did:","bold":true},{"text":" "},{"text":"rented a small space","bold":true},{"text":", "},{"text":"bought equipment","bold":true},{"text":", "},{"text":"hired staff","bold":true},{"text":" and "},{"text":"marketed","bold":true},{"text":" his product to "},{"text":"local shops and households","bold":true},{"text":"."}]},{"text":[{"text":"Result:","bold":true},{"text":" within "},{"text":"a year","bold":true},{"text":" the business became "},{"text":"profitable","bold":true},{"text":", and he started "},{"text":"expanding into nearby towns","bold":true},{"text":"."}]},{"text":[{"text":"Four reflection questions:","bold":true},{"text":" (i) identify the opportunity Tunde recognised; (ii) what resources did he mobilise; (iii) what risk$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 5, $study_guide$s did he take; (iv) how did he create value for the community."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Link each question to a dimension:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"(i) "},{"text":"Opportunity Recognition:","bold":true},{"text":" the unmet need for clean, affordable drinking water."}]},{"text":[{"text":"(ii) "},{"text":"Resource Mobilisation:","bold":true},{"text":" the rented space, the equipment, the staff (and the marketing effort)."}]},{"text":[{"text":"(iii) "},{"text":"Risk taking:","bold":true},{"text":" he spent money on rent, equipment and wages before knowing if people would buy."}]},{"text":[{"text":"(iv) "},{"text":"Value Creation:","bold":true},{"text":" safe, affordable water for the community, plus jobs for his staff."}]}]}]},{"text":[{"text":"Traps: a "},{"text":"loan from his uncle","bold":true},{"text":" belongs to Dangote's story, not Tunde's. Tunde sold to "},{"text":"local shops and households","bold":true},{"text":", not exporters, factories or government. Within a year he "},{"text":"expanded into nearby towns","bold":true},{"text":"; he did not export or sell the business."}]},{"text":[{"text":"The water problem had two sides: bottled water was "},{"text":"expensive","bold":true},{"text":", and local sources were "},{"text":"unsafe","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Dangote: 21, Kano, uncle's loan; traded sugar, rice, cement; saw Nigeria imported almost everything; started manufacturing with cement."}]},{"text":[{"text":"Entrepreneurship begins with spotting opportunities, taking risks and creating value that meets national needs."}]},{"text":[{"text":"Definition: identifying opportunities, mobilising resources, creating innovative products or services and taking risks to generate value and achieve profit."}]},{"text":[{"text":"Also a mindset: discovering problems, designing innovative solutions, delivering value to society, markets or organisations."}]},{"text":[{"text":"Formula: Opportunity + Innovation + Value Creation + Risk."}]},{"text":[{"text":"9 scopes: Technological, Social, Agricultural, Educational, Creative, Corporate, International, Public Sector, Green/Environmental."}]},{"text":[{"text":"8 characteristics: Vision, Creativity, Passion, Ability to Network, Self Confidence, Risk Taker, Resourceful, Never Give-up (Grit)."}]},{"text":[{"text":"7 dimensions: Innovativeness, Proactiveness, Risk taking, Value Creation, Opportunity Recognition, Resource Mobilisation, Autonomy."}]},{"text":[{"text":"Tunde: purified bottled water; space, equipment, staff; profitable within a year; expanding to nearby towns."}]}]}],"theory":{"itemId":"b39817d3-9f40-5d4d-a0f6-4892ed942f71","question":[{"type":"paragraph","text":[{"text":"Define entrepreneurship and explain any four of its dimensions with an example each."}]}]},"practice":[{"topic":"Week 1: Concept of Entrepreneurship","named":false}]}},{"kind":"note","itemId":"48eb34c1-a92b-5e7d-9af5-cb167fb3f55a","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Entrepreneurship Traits","body":"Entrepreneurship as a mindset and a process; the four entrepreneurial traits (opportunity seeker, risk-taker, problem solver, change agent) with what each involves and its Nigerian example; whether entrepreneurs are born or made, and the Igba Boi system; the five self-assessment questions; innovation versus creativity and the three innovator cases.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"Entrepreneurship as a mindset and a process; the four entrepreneurial traits (opportunity seeker, risk-taker, problem solver, change agent) with what each involves and its Nigerian example; whether entrepreneurs are born or made, and the Igba Boi system; the five self-assessment questions; innovation versus creativity and the three innovator cases."}],"lessons":[{"number":"2.1","title":"Entrepreneurship as a mindset, and the four traits","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Entrepreneurship","bold":true},{"text":" is not just about starting a business; it is a "},{"text":"mindset","bold":true},{"text":" and a "},{"text":"process","bold":true},{"text":" of "},{"text":"creating value","bold":true},{"text":" by "},{"text":"identifying opportunities, taking risks, and innovating","bold":true},{"text":"."}]},{"text":[{"text":"The 4 entrepreneurial traits","bold":true},{"text":" (in this order):"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Opportunity seeker","bold":true}]},{"text":[{"text":"Risk-taker","bold":true},{"text":" (full name: "},{"text":"the calculated risk-taker","bold":true},{"text":")"}]},{"text":[{"text":"Problem solver","bold":true}]},{"text":[{"text":"Change agent","bold":true}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The pictures that go with each trait: a man running with a briefcase = "},{"text":"opportunity seeker","bold":true},{"text":"; a man pulling a gauge needle towards a red \"RISK\" zone = "},{"text":"risk-taker","bold":true},{"text":"; a man fitting jigsaw-puzzle pieces beside a lightbulb = "},{"text":"problem solver","bold":true},{"text":"; a head with arrows cycling from a sad face to a happy face = "},{"text":"change agent","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The key idea is that entrepreneurship is bigger than \"opening a shop\". Someone who registers a business but never spots a need, never takes a sensible risk and never brings anything new is not really showing the entrepreneurial mindset. The three verbs in the definition (identifying opportunities, taking risks, innovating) are the heart of it, and they line up with the traits you study below."}]},{"text":[{"text":"Read the pictures as memory hooks: the runner is chasing an opening before others get there; the gauge shows someone deliberately moving$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 6, $study_guide$ into risk; the puzzle and lightbulb show fitting a solution to a problem; the sad-to-happy face shows a situation being changed for the better."}]},{"text":[{"text":"Traps:","bold":true},{"text":" the list has exactly "},{"text":"four","bold":true},{"text":" traits. Look-alikes such as \"fund manager\", \"profit maximiser\", \"market follower\", \"rent seeker\", \"cost controller\", \"policy maker\" or \"risk avoider\" are "},{"text":"not","bold":true},{"text":" on it. Watch for a list that swaps \"risk-taker\" for \"risk avoider\" or \"problem solver\" for \"profit maximiser\": one wrong word makes the option wrong."}]}]}]},{"number":"2.2","title":"The opportunity seeker and the calculated risk-taker","mustKnow":[{"type":"table","header":[[{"text":"Trait"}],[{"text":"Definition"}],[{"text":"It involves"}],[{"text":"Example"}]],"rows":[[[{"text":"Opportunity seeker","bold":true}],[{"text":"The ability to "},{"text":"identify and capitalise on market gaps or unmet needs","bold":true}],[{"text":"Market awareness, proactiveness, visionary thinking","bold":true}],[{"text":"Sim Shagaya","bold":true},{"text":" ("},{"text":"Konga","bold":true},{"text":")"}]],[[{"text":"Calculated risk-taker","bold":true}],[{"text":"Willingness to take calculated risks after assessing potential downsides","bold":true}],[{"text":"Risk assessment, tolerance for failure, a high-risk, high-reward mindset","bold":true}],[{"text":"Aliko Dangote","bold":true},{"text":" (cement, Oil & Gas)"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Sim Shagaya","bold":true},{"text":" saw (1) the "},{"text":"low penetration of formal retail","bold":true},{"text":" and (2) the "},{"text":"growing internet use","bold":true},{"text":" in Nigeria. He identified the opportunity for a "},{"text":"trusted online marketplace","bold":true},{"text":", leading him to found "},{"text":"Konga","bold":true},{"text":", "},{"text":"one of Nigeria's earliest e-commerce giants","bold":true},{"text":"."}]},{"text":[{"text":"Takeaway: opportunity-seeking "},{"text":"isn't about waiting for a \"eureka\" moment","bold":true},{"text":". It is about "},{"text":"actively looking for frustrations and inefficiencies around you","bold":true},{"text":". Sim Shagaya "},{"text":"didn't invent e-commerce","bold":true},{"text":"; he "},{"text":"applied it to the specific challenges and opportunities of the Nigerian market","bold":true},{"text":"."}]},{"text":[{"text":"Aliko Dangote","bold":true},{"text":" invested heavily in "},{"text":"cement production and Oil & Gas","bold":true},{"text":" in Nigeria "},{"text":"when others were sceptical about local manufacturing capacity","bold":true},{"text":". This calculated risk built a "},{"text":"multi-billion-dollar industrial empire","bold":true},{"text":"."}]},{"text":[{"text":"Takeaway: Dangote's risk was "},{"text":"calculated","bold":true},{"text":". He understood "},{"text":"Nigeria's infrastructure deficit","bold":true},{"text":" and bet on the "},{"text":"long-term need for local production","bold":true},{"text":". "},{"text":"Entrepreneurial risk is about managing uncertainty, not eliminating it.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Opportunity seeker in plain words:","bold":true},{"text":" a gap is something people need but cannot get, or cannot get well. "},{"text":"Market awareness","italic":true},{"text":" means knowing what is happening around you; "},{"text":"proactiveness","italic":true},{"text":" means acting before others do; "},{"text":"visionary thinking","italic":true},{"text":" means seeing where things are heading. Shagaya noticed that few Nigerians shopped in formal retail outlets while more and more were going online, and joined those two facts into one idea: a marketplace online that people could trust."}]},{"text":[{"text":"Note the point about invention. Shagaya did not create e-commerce; he adapted an existing idea to Nigeria. An exam may offer \"invented e-commerce\" or \"imported a foreign company without changes\" as distractors; the right answer is that he "},{"text":"applied it to the specific challenges and opportunities of the Nigerian market","bold":true},{"text":". Similarly, if a student notices rising smartphone use in her town and no one selling groceries online, and acts first, she is an "},{"text":"opportunity seeker","bold":true},{"text":"."}]},{"text":[{"text":"Calculated risk-taker in plain words:","bold":true},{"text":" \"calculated\" means the risk is taken "},{"text":"after assessing potential downsides","bold":true},{"text":", not blindly and not with a guarantee. "},{"text":"Risk assessment","italic":true},{"text":" is studying what could go wrong; "},{"text":"tolerance for failure","italic":true},{"text":" is being able to accept that things may not work; a "},{"text":"high-risk, high-reward","italic":true},{"text":" mindset accepts bigger risk for a bigger possible gain. Dangote was not gambling: he read the infrastructure deficit and expected Nigeria to need local production for a long time."}]},{"text":[{"text":"The final line is a favourite exam point: entrepreneurial risk is about "},{"text":"managing","bold":true},{"text":" uncertainty, "},{"text":"not eliminating","bold":true},{"text":" it. Options such as \"eliminating uncertainty before acting\", \"gambling without assessing downsides\" or \"a risk with no chance of failure\" are all wrong. A trader who studies the possible losses on a rice mill, judges that long-term demand justifies it, then invests heavily, is a "},{"text":"calculated risk-taker","bold":true},{"text":"."}]},{"text":[{"text":"Traps:","bold":true},{"text":" do not swap the \"involves\" lists. Market awareness, proactiveness and visionary thinking belong to the "},{"text":"opportunity seeker","bold":true},{"text":"; risk assessment, tolerance for failure and high-risk, high-reward belong to the "},{"text":"risk-taker","bold":true},{"text":". Do not swap the cases either: Sh$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 7, $study_guide$agaya and the e-commerce/retail/internet facts go with "},{"text":"opportunity seeker","bold":true},{"text":"; Dangote, cement, Oil & Gas, scepticism about "},{"text":"local manufacturing capacity","bold":true},{"text":" and the "},{"text":"infrastructure deficit","bold":true},{"text":" go with "},{"text":"risk-taker","bold":true},{"text":". Konga is \"one of Nigeria's earliest e-commerce giants\"; Dangote built a \"multi-billion-dollar industrial empire\"."}]}]}]},{"number":"2.3","title":"The problem solver and the change agent","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Problem solver and change agent:","bold":true},{"text":" a "},{"text":"solution-oriented mindset","bold":true},{"text":" focused on "},{"text":"fixing inefficiencies and driving change","bold":true},{"text":", often "},{"text":"creating social impact","bold":true},{"text":". "},{"text":"Entrepreneurs thrive on solving real problems.","bold":true}]},{"text":[{"text":"Dr. Akintonwa Oluwayemisi (DentistAtYourDoor):","bold":true},{"text":" solved the problem of "},{"text":"dental care access in traffic-heavy Lagos","bold":true},{"text":" by launching "},{"text":"the first mobile dental clinic","bold":true},{"text":"."}]},{"text":[{"text":"Chinedu Azodoh (MAX.ng):","bold":true},{"text":" solved the problem of "},{"text":"unsafe, informal motorcycle taxis (\"okada\")","bold":true},{"text":" by creating a "},{"text":"tech-enabled, safer, energy-saving and more reliable ride-hailing and delivery service","bold":true},{"text":"."}]},{"text":[{"text":"Takeaway: "},{"text":"the most sustainable businesses solve a persistent problem.","bold":true},{"text":" Dr. Oluwayemisi "},{"text":"didn't just complain about the traffic in Lagos; she built a mobile clinic to bring the service to the people. That's being a change agent.","bold":true}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The two traits are taught together because they work as a pair: the "},{"text":"problem solver","bold":true},{"text":" finds a fix, and the "},{"text":"change agent","bold":true},{"text":" uses that fix to change the situation for people. Social impact is the typical result: life in the community improves, not just the founder's income."}]},{"text":[{"text":"DentistAtYourDoor:","bold":true},{"text":" in Lagos, getting to a dentist can mean hours in traffic. Instead of asking patients to travel, the clinic travels to them. Remember \""},{"text":"first mobile dental clinic","bold":true},{"text":"\", not \"largest dental hospital\"."}]},{"text":[{"text":"MAX.ng:","bold":true},{"text":" okada rides were informal and unsafe. MAX.ng used technology to make motorcycle transport "},{"text":"safer, energy-saving and more reliable","bold":true},{"text":", and offered both "},{"text":"ride-hailing and delivery","bold":true},{"text":". Learn the four describing words: tech-enabled, safer, energy-saving, more reliable."}]},{"text":[{"text":"The change-agent sentence is often tested word for word: complaining about a problem is not enough; building something that brings the solution to people is what makes you a change agent. So if a student builds a cheap booking-and-delivery system that ends long queues at a borehole and improves life in the area, that is "},{"text":"problem solver and change agent","bold":true},{"text":"."}]},{"text":[{"text":"Traps:","bold":true},{"text":" do not mix up the problems. Traffic and dental care = "},{"text":"DentistAtYourDoor","bold":true},{"text":" (Dr. Akintonwa Oluwayemisi). Okada = "},{"text":"MAX.ng","bold":true},{"text":" (Chinedu Azodoh). Piracy and Nollywood belong to iROKOtv (Lesson 2.6), payments to Flutterwave, and retail/internet to Konga. \"Entrepreneurs thrive on "},{"text":"solving real problems","bold":true},{"text":"\", not on \"eliminating uncertainty\" or \"eureka moments\"."}]}]}]},{"number":"2.4","title":"Are entrepreneurs born or made?","mustKnow":[{"type":"table","header":[[{"text":"Argument"}],[{"text":"What it says"}]],"rows":[[[{"text":"Natural Traits (Born)","bold":true}],[{"text":"Some people have "},{"text":"high energy, natural charisma, and high risk tolerance from birth","bold":true},{"text":". For some, "},{"text":"inherent qualities like resilience, creativity, or extraversion appear early","bold":true},{"text":"."}]],[[{"text":"Nurtured Traits (Made)","bold":true}],[{"text":"Skills developed through "},{"text":"education, mentorship, and experience","bold":true},{"text":". "},{"text":"Accounting, management, marketing, and emotional intelligence are learned skills.","bold":true}]]]},{"type":"paragraph","text":[{"text":"The Igbo Apprenticeship System (Igba Boi)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The world's largest business incubator is right here in Nigeria.","bold":true}]},{"text":[{"text":"Its 3 steps, in order:"}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Young people are "},{"text":"picked","bold":true},{"text":" (often with "},{"text":"no capital","bold":true},{"text":")."}]},{"text":[{"text":"They are "},{"text":"nurtured","bold":true},{"text":" through "},{"text":"years of mentorship","bold":true},{"text":"."}]},{"text":[{"text":"They are "},{"text":"\"settled\" (funded)","bold":true},{"text":" to start their own."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"If entrepreneurship were only natural, the Igba Boi system "},{"text":"wouldn't have a near 100% success rate","bold":true},{"text":". It "},{"text":"proves entrepreneurs can be made","bold":true},{"text":"; it is "},{"text":"the perfect example of Nurture","bold":true},{"text":"."}]},{"text":[{"text":"\""},{"text":"These boys aren't born knowing the price of spare parts.","bold":true},{"text":"\" They are taught "},{"text":"trade, negotiation, and supply chain management","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The \"born\" side says $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 8, $study_guide$some people simply arrive with the energy, charm and comfort with risk that business needs, and that qualities like resilience, creativity or being outgoing (extraversion) can show from childhood. The \"made\" side says the important business skills can be learned at school, from a mentor or on the job."}]},{"text":[{"text":"Igba Boi","bold":true},{"text":" is the strongest evidence for \"made\". A young person, usually with no money, joins an established trader, learns the business over several years, and at the end the master \"settles\" him, meaning he is given funds to open his own business. Picture a 14-year-old who serves a spare-parts dealer in Onitsha for seven years and is then funded to open his own shop: that is the Igba Boi system."}]},{"text":[{"text":"The near 100% success rate is the argument: if success depended only on inborn traits, a system that takes ordinary young people and trains them would not work so reliably. The spare-parts line makes the same point: nobody is born knowing prices; it is taught."}]},{"text":[{"text":"Traps:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Keep the step order: "},{"text":"picked, nurtured, settled","bold":true},{"text":". Any order with \"settled\" first or in the middle is wrong."}]},{"text":[{"text":"\"Settled\" = "},{"text":"funded to start his own business","bold":true},{"text":", not \"employed permanently\" or \"enrolled in school\"."}]},{"text":[{"text":"The success rate is "},{"text":"near 100%","bold":true},{"text":", not 25% or 50%."}]},{"text":[{"text":"Igba Boi proves "},{"text":"nurture","bold":true},{"text":" (made), not nature (born)."}]},{"text":[{"text":"Born list: high energy, natural charisma, high risk tolerance; early-appearing qualities: resilience, creativity, extraversion. Made list: accounting, management, marketing, emotional intelligence. "},{"text":"Emotional intelligence is a learned (made) skill","bold":true},{"text":"; "},{"text":"natural charisma and extraversion are born","bold":true},{"text":" qualities."}]},{"text":[{"text":"What apprentices are taught: "},{"text":"trade, negotiation, supply chain management","bold":true},{"text":". Do not confuse with the opportunity-seeker list (market awareness, proactiveness, visionary thinking)."}]}]}]}]}]},{"number":"2.5","title":"Assess your entrepreneurial profile","mustKnow":[{"type":"paragraph","text":[{"text":"The self-assessment has "},{"text":"5 labelled dimensions","bold":true},{"text":", each with its question:"}]},{"type":"table","header":[[{"text":"Dimension"}],[{"text":"Question it asks"}]],"rows":[[[{"text":"Opportunity Seeking","bold":true}],[{"text":"How often do you spot problems or gaps around you?"}]],[[{"text":"Risk Tolerance","bold":true}],[{"text":"How comfortable are you with calculated, uncertain outcomes?"}]],[[{"text":"Problem-Solving","bold":true}],[{"text":"How quickly do you move from identifying a problem to brainstorming solutions?"}]],[[{"text":"Creativity","bold":true}],[{"text":"How easily do you generate new ideas or unconventional approaches?"}]],[[{"text":"Resilience","bold":true}],[{"text":"How do you bounce back from setbacks?"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"This is a mirror: each question asks how strongly you show one trait. The first three match the traits you have already met (opportunity seeker, risk-taker, problem solver); creativity links to Lesson 2.6; resilience is about recovering after failure."}]},{"text":[{"text":"Match by key words: \"spot problems or gaps\" = "},{"text":"opportunity seeking","bold":true},{"text":"; \"calculated, uncertain outcomes\" = "},{"text":"risk tolerance","bold":true},{"text":"; \"from identifying a problem to brainstorming solutions\" = "},{"text":"problem-solving","bold":true},{"text":"; \"new ideas or unconventional approaches\" = "},{"text":"creativity","bold":true},{"text":"; \"bounce back from setbacks\" = "},{"text":"resilience","bold":true},{"text":"."}]},{"text":[{"text":"Traps:","bold":true},{"text":" there are "},{"text":"five","bold":true},{"text":" labelled dimensions. \"Emotional intelligence\" is "},{"text":"not","bold":true},{"text":" one of them (it is a learned skill in Lesson 2.4). Do not confuse \"spot problems\" (opportunity seeking) with \"move from a problem to solutions\" (problem-solving)."}]}]}]},{"number":"2.6","title":"Innovators and creative thinkers","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Innovation","bold":true},{"text":" introduces "},{"text":"new products, services, or business models","bold":true},{"text":"."}]},{"text":[{"text":"Creativity","bold":true},{"text":" is "},{"text":"thinking outside conventional frameworks to develop unique solutions","bold":true},{"text":"."}]},{"text":[{"text":"Creativity involves having a better idea; innovation involves making it a reality.","bold":true}]}]},{"type":"table","header":[[{"text":"Person"}],[{"text":"Venture"}],[{"text":"What they did"}]],"rows":[[[{"text":"Bolanle Austen-Peters","bold":true}],[{"text":"Terra Kulture","bold":true}],[{"text":"Reimagined the "},{"text":"cultural space in Lagos","bold":true},{"text":", creating a vibrant hub for "},{"text":"arts, dining, and theatre","bold":true}]],[[{"text":"Jason Njoku","bold":true}],[{"text":"iROKOtv","bold":true}],[{"text":"Revolutionised "},{"text":"Nollywood content distribution","bold":true},{"text":" by "},{"text":"moving it online","bold":true},{"text":", solving "},{"text":"piracy and access","bold":true},{"text":" issues"}]],[[{"text":"Olugbenga Agboola & Iyinoluwa Aboyeji","bold":true}],[{"text":"Flutterwave","bold":true}],[{"text":"Solved the "},{"text":"payment challenge in Africa","bold":true},{"text":" by providing a "},{"text":"payment infrastructure for global merchants and payment service providers","bold":true},{"text":" across the continent"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cre$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 9, $study_guide$ativity happens in the head; innovation happens in the market. If one person sketches a clever solar phone charger and another later manufactures and sells it, the sketch is "},{"text":"creativity","bold":true},{"text":" and the launch is "},{"text":"innovation","bold":true},{"text":". The classic trap reverses the two (\"innovation is the idea, creativity makes it real\"): that is wrong."}]},{"text":[{"text":"Terra Kulture","bold":true},{"text":" took the idea of a cultural centre and made it a lively place where art, food and theatre meet in one spot in Lagos."}]},{"text":[{"text":"iROKOtv","bold":true},{"text":" changed how Nollywood films reach viewers: by putting them online it cut piracy and made films easier to access."}]},{"text":[{"text":"Flutterwave","bold":true},{"text":" built the payment \"pipes\" that let global merchants and payment service providers accept payments across Africa."}]},{"text":[{"text":"Traps:","bold":true},{"text":" all three (Terra Kulture, iROKOtv, Flutterwave) illustrate "},{"text":"innovators and creative thinkers","bold":true},{"text":", not risk-takers or Igba Boi. Flutterwave has "},{"text":"two","bold":true},{"text":" founders, Olugbenga Agboola and Iyinoluwa Aboyeji, paired together. Do not pair Jason Njoku with Flutterwave or MAX.ng; his venture is "},{"text":"iROKOtv","bold":true},{"text":". Of all the people in this topic, only Austen-Peters, Njoku, Agboola and Aboyeji are innovator examples; Shagaya, Dangote, Oluwayemisi and Azodoh illustrate the other traits."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Entrepreneurship = a mindset and a process of creating value by identifying opportunities, taking risks and innovating."}]},{"text":[{"text":"Four traits: opportunity seeker, risk-taker, problem solver, change agent."}]},{"text":[{"text":"Opportunity seeker = spots market gaps or unmet needs (market awareness, proactiveness, visionary thinking): Sim Shagaya, Konga."}]},{"text":[{"text":"Calculated risk-taker = takes risks after assessing downsides (risk assessment, tolerance for failure, high-risk high-reward): Dangote, cement and Oil & Gas; risk is managing uncertainty, not eliminating it."}]},{"text":[{"text":"Problem solver and change agent = fixes inefficiencies, drives change, often social impact: DentistAtYourDoor (first mobile dental clinic), MAX.ng (safer okada); the most sustainable businesses solve a persistent problem."}]},{"text":[{"text":"Born: high energy, charisma, risk tolerance; made: education, mentorship, experience (accounting, management, marketing, emotional intelligence)."}]},{"text":[{"text":"Igba Boi: picked (no capital), nurtured (years of mentorship), settled (funded); near 100% success; proves entrepreneurs can be made."}]},{"text":[{"text":"Self-assessment: opportunity seeking, risk tolerance, problem-solving, creativity, resilience."}]},{"text":[{"text":"Creativity = the better idea; innovation = making it real: Terra Kulture, iROKOtv, Flutterwave."}]}]}],"theory":{"itemId":"93bcc233-d008-5644-a9ad-a5a0ebe330f8","question":[{"type":"paragraph","text":[{"text":"Are entrepreneurs born or made? Use the Igba Boi system to support your answer."}]}]},"practice":[{"topic":"Weeks 2-3: Entrepreneurship Traits","named":false}]}},{"kind":"note","itemId":"12f9620e-b9f1-5be2-a01d-2797c65109dd","sourceKey":"guide-topic:3","position":3,"payload":{"title":"Innovation and Change","body":"What innovation is (McKinsey, 2022) and how it differs from invention; the four dimensions of innovation with their Nigerian examples; how knowledge fuels innovation (Knowledge Management, the pyramid, the DIKW model); Kurt Lewin's 3-stage change model; and how external shocks force a business to pivot. By the end you should be able to define innovation and explain its dimensions, analyse the relationship between knowledge and innovation, and apply the principles of change management to entrepreneurial ventures.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"What innovation is (McKinsey, 2022) and how it differs from invention; the four dimensions of innovation with their Nigerian examples; how knowledge fuels innovation (Knowledge Management, the pyramid, the DIKW model); Kurt Lewin's 3-stage change model; and how external shocks force a business to pivot. By the end you should be able to define innovation and explain its dimensions, analyse the relationship between knowledge and innovation, and apply the principles of change management to entrepreneurial ventures."}],"lessons":[{"number":"3.1","title":"What innovation is","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Innovation (McKinsey, 2022):","bold":true},{"text":" the systematic practice of developing and marketing breakthrough products and services for adoption by customers."}]},{"text":[{"text":"Innovation (second definition):","bold":true},{"text":" the successful implementation of new ideas that create value."}]},{"text":[{"text":"Innovation is "},{"text":"not just invention","bold":true},{"text":"; it is about "},{"text":"making an idea work in the real world","bold":true},{"text":"."}]},{"text":[{"text":"The four dimensions of innovation","bold":true},{"text":", in order:"}]}]},{"type":"table","header":[[{"text":"Dimension"}],[{"text":"Short meaning"}]],"rows":[[[{"text":"1. Product Innovation"}],[{"text":"What","bold":true},{"text":" you sell"}]],[[{"text":"2. Process Innovation"}],[{"text":"How","bold":true},{"text":" you create it"}]],[[{"text":"3. Market Innovation"}],[{"text":"Who","bold":true},{"text":" you sell to and how you reach them"}]],[[{"text":"4. Organisational Innovation"}],[{"text":"How you "},{"text":"structure and manage","bold":true},{"text":" your company"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Read the McKinsey definition word by word: "},{"text":"systematic","italic":true},{"text":" (planned, not a lucky accident), "},{"text":"developing and marketing","ital$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 10, $study_guide$ic":true},{"text":" (you must both build it and sell it), "},{"text":"breakthrough products and services","italic":true},{"text":", "},{"text":"for adoption by customers","italic":true},{"text":" (if customers do not take it up, it has not succeeded). The citation is "},{"text":"McKinsey, 2022","bold":true},{"text":". An exam may swap in the World Bank, OECD or Kurt Lewin; none of these gave this definition."}]},{"text":[{"text":"The second definition puts the weight on "},{"text":"successful implementation","bold":true},{"text":" and "},{"text":"value","bold":true},{"text":". An idea sitting in your notebook, or even a working prototype nobody uses, is an invention, not an innovation. Innovation is invention plus making it work in the real world."}]},{"text":[{"text":"Trap: \"Invention creates value while innovation only generates ideas\" is backwards. Innovation is the one tied to value and real-world use."}]},{"text":[{"text":"The four dimensions are easy to remember as four questions a business owner asks: "},{"text":"What","bold":true},{"text":" do I sell? (product) "},{"text":"How","bold":true},{"text":" do I make or deliver it? (process) "},{"text":"Who","bold":true},{"text":" do I sell to, and how do I reach them? (market) "},{"text":"How","bold":true},{"text":" is my company run? (organisational)."}]},{"text":[{"text":"There are exactly "},{"text":"four","bold":true},{"text":" dimensions. \"Legal\", \"political\", \"financial\" or \"refreeze\" innovation are not among them; \"refreeze\" belongs to Lewin's change model in Lesson 3.4."}]},{"text":[{"text":"The pictures that go with the four dimensions help you hold the ideas: a man inside a phone surrounded by shopping icons and money signs (product: the thing you sell), a head with arrows cycling from a sad face to a happy face (process: improving how something is done), a man pulling a gauge needle towards \"RISK\" (market: reaching into new, riskier targets), and a man fitting jigsaw pieces beside a lightbulb (organisational: rearranging how the company fits together)."}]}]}]},{"number":"3.2","title":"The four dimensions with examples","mustKnow":[{"type":"table","header":[[{"text":"Dimension"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"Product Innovation"}],[{"text":"Improving a product or creating a totally new one"}],[{"text":"Cowrywise and Piggyvest","bold":true},{"text":" took the traditional wooden "},{"text":"Kolo","bold":true},{"text":" (savings box) and moved it to an "},{"text":"app with interest rates","bold":true}]],[[{"text":"Process Innovation"}],[{"text":"Changing how a product is created or delivered to "},{"text":"lower cost or increase speed","bold":true}],[{"text":"Chowdeck and Glovo","bold":true},{"text":": the logistics process of using "},{"text":"bikes/bicycles","bold":true},{"text":" that allowed delivery in Lagos traffic within "},{"text":"30 minutes","bold":true},{"text":" (beating the traffic)"}]],[[{"text":"Market Innovation ("},{"text":"New Targets","bold":true},{"text":")"}],[{"text":"Finding new markets or packaging for existing products"}],[{"text":"The \"Sachet Economy\"","bold":true},{"text":": most Nigerians cannot buy big tins of "},{"text":"Peak Milk","bold":true},{"text":"; innovating the packaging (sachets) opened a massive market for "},{"text":"low-income earners","bold":true}]],[[{"text":"Organisational Innovation ("},{"text":"New Structures","bold":true},{"text":")"}],[{"text":"Changing workplace culture or structure"}],[{"text":"Andela/Tech Startups","bold":true},{"text":": moving from the "},{"text":"\"Oga must see you at your desk\"","bold":true},{"text":" mentality to a "},{"text":"results-based culture","bold":true},{"text":" where you can "},{"text":"work from home","bold":true}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Product innovation (Cowrywise and Piggyvest).","bold":true},{"text":" The Kolo is the wooden box many Nigerian children dropped coins into and broke open later. It earned nothing. Cowrywise and Piggyvest kept the same habit (putting money aside) but changed the product itself: it now lives in an app and pays interest. The thing you sell is new or improved, so this is product innovation."}]},{"text":[{"text":"Process innovation (Chowdeck and Glovo).","bold":true},{"text":" The food is not new; restaurants already cooked it. What is new is "},{"text":"how it gets to you","bold":true},{"text":": bikes and bicycles weave through Lagos traffic and deliver within "},{"text":"30 minutes","bold":true},{"text":". Process innovation aims to "},{"text":"lower cost or increase speed","bold":true},{"text":". Watch the number: 30 minutes, not 15, 45 or 60. And note the innovation is the "},{"text":"logistics process","bold":true},{"text":", not a new type of food."}]},{"text":[{"text":"Market innovation (the Sachet Economy).","bold":true},{"text":" Peak Milk is the same milk whether in a big tin or a sachet. Companies realised most Nigerians cannot afford the big tin, so they changed the "},{"text":"packaging","bold":true},{"text":" and reached a huge new market of "},{"text":"low-income earners","bold":true},{"text":". Its label is "},{"text":"New Targets","bold":true},{"text":": same product, new customers. The definition covers both \"new markets\" and \"packaging for existing products\"."}]},{"text":[{"text":"Organisational innovation (Andela and tech startups).","bold":true},{"text":" Nothing about the product, delivery or customers changes here; what changes is "},{"text":"how the workplace is run","bold":true},{"text":". Instead of a boss (\"Oga\") needing to see you physically at your desk, staff are judged on results and can work from home. Its label is "},{"text":"New Structures","bold":true},{"text":"."}]},{"text":[{"text":"Quick test for any scenario question: ask what actually changed."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The thing sold changed (an esusu savings habit turned i$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 11, $study_guide$nto an interest-paying app) = "},{"text":"product","bold":true},{"text":"."}]},{"text":[{"text":"The way it is made or delivered changed (vans swapped for motorcycle riders to be faster and cheaper) = "},{"text":"process","bold":true},{"text":"."}]},{"text":[{"text":"The customers or the packaging changed (a 1kg detergent bag also sold in small single-use packs) = "},{"text":"market","bold":true},{"text":"."}]},{"text":[{"text":"The workplace culture or structure changed (a bank letting staff work from home, judged by results) = "},{"text":"organisational","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Label trap: "},{"text":"New Targets","bold":true},{"text":" = market innovation; "},{"text":"New Structures","bold":true},{"text":" = organisational innovation. Do not swap them. \"Organisational\" and \"Organizational\" are the same word in two spellings."}]}]}]},{"number":"3.3","title":"Knowledge and innovation","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Innovation doesn't happen in a vacuum. It is fuelled by knowledge.","bold":true}]},{"text":[{"text":"Knowledge Management (KM):","bold":true},{"text":" the systematic process of "},{"text":"creating, sharing, using, and managing","bold":true},{"text":" an organisation's knowledge and information."}]},{"text":[{"text":"The Pyramid","bold":true},{"text":" (from the base upwards):"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Data:","bold":true},{"text":" raw facts (e.g. \"Rice is 80k per bag\")."}]},{"text":[{"text":"Information:","bold":true},{"text":" context (e.g. \"Rice price went up because of the border closure\")."}]},{"text":[{"text":"Knowledge:","bold":true},{"text":" application (e.g. \"I should switch to selling local rice or cassava alternatives\")."}]},{"text":[{"text":"Innovation:","bold":true},{"text":" creating value from that knowledge."}]}]}]},{"text":[{"text":"Balogun market:","bold":true},{"text":" every trader in Balogun market has data (prices). Only the innovators use that data to "},{"text":"predict what will sell next Christmas","bold":true},{"text":"."}]},{"text":[{"text":"DIKW Knowledge Management Model","bold":true},{"text":" (pyramid diagram):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Main labels, top to bottom: "},{"text":"Wisdom, Knowledge, Information, Data, Facts, Measurements","bold":true},{"text":"."}]},{"text":[{"text":"Side labels, top to bottom: "},{"text":"Focus, Adjust, Compare, Sample, Observe","bold":true},{"text":"."}]},{"text":[{"text":"D-I-K-W = "},{"text":"Data, Information, Knowledge, Wisdom","bold":true},{"text":"; "},{"text":"Wisdom","bold":true},{"text":" sits at the top."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Not in a vacuum\" means innovation does not appear from nowhere, by luck or only from government policy. It grows out of what a person or business knows. That is why businesses manage knowledge deliberately (KM): they create it, share it, use it and manage it, in that order of the definition."}]},{"text":[{"text":"Walk up the pyramid with the rice example:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Data","bold":true},{"text":" is a bare fact with no explanation: rice costs 80k (₦80,000) a bag."}]},{"text":[{"text":"Information","bold":true},{"text":" adds context, the \"why\": the price rose because of the "},{"text":"border closure","bold":true},{"text":". (Trap: not fuel subsidy removal, the dollar rate or the Okada ban.)"}]},{"text":[{"text":"Knowledge","bold":true},{"text":" is putting that understanding to use, the \"so what do I do\": switch to local rice or cassava alternatives."}]},{"text":[{"text":"Innovation","bold":true},{"text":" is the top step: actually creating value from that knowledge."}]}]}]},{"text":[{"text":"Keyword pairs to memorise: Data = "},{"text":"raw facts","bold":true},{"text":"; Information = "},{"text":"context","bold":true},{"text":"; Knowledge = "},{"text":"application","bold":true},{"text":"; Innovation = "},{"text":"creating value","bold":true},{"text":". An exam will give you one statement and ask which level it is, or will scramble the order. The correct order upwards is Data, Information, Knowledge, Innovation."}]},{"text":[{"text":"The Balogun point: having data is common; every trader knows today's prices. What makes the innovator different is not collecting more price lists but "},{"text":"using","bold":true},{"text":" the data to look ahead (what will sell next Christmas)."}]},{"text":[{"text":"The DIKW diagram is a second version of the same idea. Its top level is "},{"text":"Wisdom","bold":true},{"text":", not innovation; the four letters are Data, Information, Knowledge, Wisdom. Beneath Data it adds "},{"text":"Facts","bold":true},{"text":" and "},{"text":"Measurements","bold":true},{"text":" as the raw base. The side words describe what you do as you climb: "},{"text":"Observe","bold":true},{"text":", "},{"text":"Sample","bold":true},{"text":", "},{"text":"Compare","bold":true},{"text":", "},{"text":"Adjust","bold":true},{"text":", "},{"text":"Focus","bold":true},{"text":" (read from the bottom up). So in the simple pyramid the top is Innovation; in the DIKW model the top is Wisdom. Know which one a question is asking about."}]}]}]},{"number":"3.4","title":"Change and innovation: Kurt Lewin's model","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Naturally, humans are "},{"text":"averse to change","bold":true},{"text":". They prefer "},{"text":"\"The Devil they know.\"","bold":true}]},{"text":[{"text":"Kurt Lewin","bold":true},{"text":" proposed a "},{"text":"3-stage model","bold":true},{"text":" for planning change:"}]}]},{"type":"table","header":[[{"text":"Stage"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"1. "},{"text":"Unfreeze","bold":true}],[{"text":"Realising the old way is dangerous or expensive"}],[{"text":"Kerosene stoves"}]$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 12, $study_guide$],[[{"text":"2. "},{"text":"Change","bold":true}],[{"text":"The messy transition to the new way"}],[{"text":"Switching to gas cylinders"}]],[[{"text":"3. "},{"text":"Refreeze","bold":true}],[{"text":"Making the new way the habit"}],[]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Lagos Okada ban:","bold":true},{"text":" when Lagos banned Okadas in certain areas, the "},{"text":"Change","bold":true},{"text":" phase was chaotic; people had to trek. Eventually people "},{"text":"Refroze","bold":true},{"text":" into using buses or trekking."}]},{"text":[{"text":"You cannot just announce innovation.","bold":true},{"text":" You have to "},{"text":"Unfreeze","bold":true},{"text":" people first: convince them why the old way is bad."}]},{"text":[{"text":"Diagram: melting ice cubes (Unfreeze), a splash of water (Change), solid ice cubes (Refreeze)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"The Devil they know\" is short for the saying \"better the devil you know than the angel you don't\": people would rather keep a familiar bad situation than risk an unfamiliar one. That is why new ideas meet resistance, and why change has to be planned."}]},{"text":[{"text":"Picture the ice. "},{"text":"Unfreeze","bold":true},{"text":": the block melts, meaning people let go of the old way once they see it is dangerous or expensive (the kerosene stove that can explode or keeps costing more). "},{"text":"Change","bold":true},{"text":": the water splashes about, meaning the actual switch (to gas cylinders) is messy and uncomfortable. "},{"text":"Refreeze","bold":true},{"text":": the water sets into new ice cubes, meaning the new way hardens into the normal habit."}]},{"text":[{"text":"Order is always "},{"text":"Unfreeze, Change, Refreeze","bold":true},{"text":". Traps: \"Refreeze, Change, Unfreeze\" or putting Refreeze in the middle. There is no \"Pivot\", \"Planning\" or \"Adoption\" stage in Lewin's model."}]},{"text":[{"text":"Kerosene-to-gas: "},{"text":"realising","italic":true},{"text":" kerosene is dangerous or expensive is Unfreeze; the "},{"text":"actual messy switching","italic":true},{"text":" to gas cylinders is Change; gas becoming what everyone just uses is Refreeze."}]},{"text":[{"text":"Okada ban: the chaotic period of trekking = "},{"text":"Change","bold":true},{"text":"; settling into buses or trekking as the new normal = "},{"text":"Refreeze","bold":true},{"text":"."}]},{"text":[{"text":"Applying it to your own venture: before you introduce anything new to staff or customers, first show them why the old way is bad. For example, a business owner who holds meetings showing staff how much money and time old manual record books are costing, "},{"text":"before","italic":true},{"text":" bringing in new software, is "},{"text":"unfreezing","bold":true},{"text":". Announcing the change and \"handling resistance later\" skips the first stage."}]},{"text":[{"text":"Lewin is the name tied to the "},{"text":"3-stage change model","bold":true},{"text":". He did not give the four dimensions, the McKinsey definition or the DIKW pyramid."}]}]}]},{"number":"3.5","title":"Adapting to external change (the pivot)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"External shocks","bold":true},{"text":" ("},{"text":"Dollar rate","bold":true},{"text":", "},{"text":"Fuel subsidy removal","bold":true},{"text":") force innovation. Adapting to external change is called "},{"text":"the pivot","bold":true},{"text":"."}]},{"text":[{"text":"Case study: Fuel Subsidy Removal (2023/2024)","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Reaction:","bold":true},{"text":" transport costs "},{"text":"tripled","bold":true},{"text":"."}]},{"text":[{"text":"Innovation:","bold":true},{"text":" companies shifted to "},{"text":"remote work","bold":true},{"text":" ("},{"text":"Organisational Change","bold":true},{"text":") or "},{"text":"staff buses","bold":true},{"text":"; some mechanics started "},{"text":"converting cars to CNG","bold":true},{"text":" ("},{"text":"Product/Process Change","bold":true},{"text":")."}]}]}]},{"text":[{"text":"Lesson:","bold":true},{"text":" change is "},{"text":"not always voluntary","bold":true},{"text":". Sometimes "},{"text":"the economy forces you to innovate","bold":true},{"text":"."}]},{"text":[{"text":"Diagram: a country road blocked by a barrier with a \"ROAD CLOSED\" sign."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lewin's model is about change you plan. This lesson covers change you did not choose: a shock from outside the business, like a jump in the dollar rate or the removal of fuel subsidy. The \"ROAD CLOSED\" picture captures it: the usual road is blocked, so you must turn and find another route. That turn is the "},{"text":"pivot","bold":true},{"text":"."}]},{"text":[{"text":"Fuel subsidy removal: memorise the date "},{"text":"2023/2024","bold":true},{"text":" and the reaction, transport costs "},{"text":"tripled","bold":true},{"text":" (not doubled or halved)."}]},{"text":[{"text":"Match each response to its type, because exams test the labels:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Remote work = "},{"text":"Organisational Change","bold":true},{"text":" (how the company is run changed; compare Andela in Lesson 3.2)."}]},{"text":[{"text":"Staff buses = another company response to the transport cost."}]},{"text":[{"text":"Mechanics converting cars to "},{"text":"CNG","bold":true},{"text":" = "},{"text":"Product/Process Change","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Trap: \"selling milk in sachets\" was "},{"text":"not","bold":true},{"text":" a response to fuel subsidy removal; it is the market innovation example (the Sachet Economy)."}]},{"text":[{"text":"The lesson is the opposite of waiting: shocks do not reduce the need for innovation and you cannot wait for a stable economy; sometimes the economy forc$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 13, $study_guide$es you to innovate. A scenario such as a fashion brand that imported fabric switching to locally woven aso-oke after the naira falls against the dollar is a pivot, adapting to external change."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Innovation = the systematic practice of developing and marketing breakthrough products and services for adoption by customers (McKinsey, 2022); also, the successful implementation of new ideas that create value. Not just invention: making an idea work in the real world."}]},{"text":[{"text":"Four dimensions: Product (what you sell), Process (how you create it), Market (who you sell to and how you reach them), Organisational (how you structure and manage your company)."}]},{"text":[{"text":"Examples: Cowrywise/Piggyvest and the Kolo = product; Chowdeck/Glovo bikes, 30 minutes = process; Peak Milk sachets for low-income earners = market (New Targets); Andela results-based, work-from-home culture = organisational (New Structures)."}]},{"text":[{"text":"Innovation is fuelled by knowledge. KM = creating, sharing, using and managing an organisation's knowledge and information."}]},{"text":[{"text":"Pyramid: Data (raw facts) → Information (context) → Knowledge (application) → Innovation (creating value). Rice 80k / border closure / switch to local rice or cassava."}]},{"text":[{"text":"DIKW = Data, Information, Knowledge, Wisdom; Wisdom at the top, Facts and Measurements at the base."}]},{"text":[{"text":"Humans prefer \"The Devil they know\". Kurt Lewin: Unfreeze, Change, Refreeze (kerosene to gas; Okada ban). Unfreeze people before announcing innovation."}]},{"text":[{"text":"External shocks (dollar rate, fuel subsidy removal) force a pivot. Subsidy removal 2023/2024: transport costs tripled; remote work (organisational), staff buses, CNG conversion (product/process). Change is not always voluntary."}]}]}],"theory":{"itemId":"3e8ac2e5-6278-5151-a752-e50ac292aa30","question":[{"type":"paragraph","text":[{"text":"Define innovation and explain its four dimensions, giving one Nigerian example of each."}]}]},"practice":[{"topic":"Weeks 4-5: Innovation and Change","named":false}]}},{"kind":"note","itemId":"0f65c04f-089a-592e-91d0-7932d6e2e364","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Enterprise Formation (Business Plan)","body":"The three learning outcomes; the business plan (Bank of America, 2025) and its 8 core components in order; the Swift Clean case and its 7 stages; sole proprietorship, limited liability partnership, general partnership and cooperative with their cited definitions; the comparison table of liability, key disadvantage, best for and key advantage.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The three learning outcomes; the business plan (Bank of America, 2025) and its 8 core components in order; the Swift Clean case and its 7 stages; sole proprietorship, limited liability partnership, general partnership and cooperative with their cited definitions; the comparison table of liability, key disadvantage, best for and key advantage."}],"lessons":[{"number":"4.1","title":"Learning outcomes and the basics of a business plan","mustKnow":[{"type":"paragraph","text":[{"text":"This topic (Weeks 6 and 7, Enterprise Formation: Business Plan) has "},{"text":"3 learning outcomes","bold":true},{"text":". By the end you should be able to:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify","bold":true},{"text":" the different forms of business ownership in Nigeria."}]},{"text":[{"text":"Evaluate","bold":true},{"text":" the advantages and disadvantages of each ownership type."}]},{"text":[{"text":"Develop","bold":true},{"text":" the outline of a simple business plan."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Business plan:","bold":true},{"text":" a strategic roadmap detailing a company's goals and the methods to achieve them "},{"text":"(Bank of America, 2025)","bold":true},{"text":"."}]},{"text":[{"text":"A business plan is "},{"text":"not just for investors","bold":true},{"text":"; it is your "},{"text":"foundational roadmap","bold":true},{"text":" that forces you to:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"think through every step,"}]},{"text":[{"text":"identify weaknesses early,"}]},{"text":[{"text":"align your team."}]}]}]},{"text":[{"text":"You "},{"text":"don't need 50 pages","bold":true},{"text":": start with a "},{"text":"clear, practical and brief mini plan","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Core components of a simple plan (8), in order:","bold":true}]},{"type":"table","header":[[{"text":"No."}],[{"text":"Component"}],[{"text":"What it answers"}]],"rows":[[[{"text":"1"}],[{"text":"Executive Summary"}],[{"text":"Summary of the plan"}]],[[{"text":"2"}],[{"text":"Company Description"}],[{"text":"What does your company do?"}]],[[{"text":"3"}],[{"text":"Business Opportunity"}],[{"text":"What is the market potential?"}]],[[{"text":"4"}],[{"text":"Competitor Analysis"}],[{"text":"What makes you stand out?"}]],[[{"text":"5"}],[{"text":"SWOT Analysis"}],[{"text":"Strengths, Weaknesses, Opportunities and Threats"}]],[[{"text":"6"}],[{"text":"Revenue Model"}],[{"text":"How will you make money?"}]],[[{"text":"7"}],[{"text":"Financial Projection"}],[{"text":"Company's growth prediction"}]],[[{"text":"8"}],[{"text":"Team"}],[{"text":"How you structure and manage your company"}]]]},{"type":"paragraph","text":[{"text":"The 8 components are often shown as two rows of four boxes: top row Executive Summary, Company Description, Business Opportunity, Competitor Analysis; bottom row SWOT Analysis, Revenue Model, Financial Projection, Team."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Think of the business plan as a map for a journey from Akoka to Lekki: the goals are the destination, the methods are the route. The key words in the definition are "},{"text":"strat$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 14, $study_guide$egic roadmap","bold":true},{"text":", "},{"text":"goals","bold":true},{"text":" and "},{"text":"methods","bold":true},{"text":". Do not confuse it with a record of past profits, a partnership agreement or a registration certificate; those are different things."}]},{"text":[{"text":"The citation is "},{"text":"Bank of America (2025)","bold":true},{"text":". Other names you meet in this topic (Tyler, Beattie, Bloomenthal, Lip) belong to the ownership forms, not to the business plan."}]},{"text":[{"text":"The plan is first for "},{"text":"you","bold":true},{"text":", the founder. An exam may offer \"it is needed only when you want investors\" or \"it must be at least 50 pages\": both are false. Equally, a plan does "},{"text":"not guarantee","bold":true},{"text":" that investors will fund you; the three things it helps you do are think through every step, identify weaknesses early and align your team."}]},{"text":[{"text":"If a friend says he cannot start until he writes a 50-page plan, the right advice is to start with a clear, practical and brief "},{"text":"mini plan","bold":true},{"text":"."}]},{"text":[{"text":"Learn each component by the question it answers:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"\"Summary of the plan\" = "},{"text":"Executive Summary","bold":true},{"text":" (the short overview at the front)."}]},{"text":[{"text":"\"What does your company do?\" = "},{"text":"Company Description","bold":true},{"text":"."}]},{"text":[{"text":"\"What is the market potential?\" = "},{"text":"Business Opportunity","bold":true},{"text":". If a food delivery startup estimates how many office workers in Ikeja would pay for its service, that is Business Opportunity."}]},{"text":[{"text":"\"What makes you stand out?\" = "},{"text":"Competitor Analysis","bold":true},{"text":" (how you compare with rivals)."}]},{"text":[{"text":"SWOT","bold":true},{"text":" = Strengths, Weaknesses, Opportunities, Threats. Strengths and weaknesses describe your own business; opportunities and threats are what you face around you. Watch for fake expansions such as \"Strategy\", \"Workforce\" or \"Trends\"."}]},{"text":[{"text":"\"How will you make money?\" = "},{"text":"Revenue Model","bold":true},{"text":". A printing shop that charges per page and sells monthly packages to student associations is describing its Revenue Model."}]},{"text":[{"text":"\"Company's growth prediction\" = "},{"text":"Financial Projection","bold":true},{"text":". A caterer predicting how her company will grow over the next three years is writing her Financial Projection."}]},{"text":[{"text":"\"How you structure and manage your company\" = "},{"text":"Team","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Traps:","bold":true},{"text":" Revenue Model (how money comes in) vs Financial Projection (how the company is predicted to grow). Business Opportunity (market potential) vs Competitor Analysis (standing out). Items such as "},{"text":"Go-to-Market","bold":true},{"text":", "},{"text":"USP","bold":true},{"text":", "},{"text":"Milestones","bold":true},{"text":" and "},{"text":"Target Market","bold":true},{"text":" are stages in the Swift Clean case (Lesson 4.2), "},{"text":"not","bold":true},{"text":" among the 8 core components. \"Patronage refund\" and \"Key Disadvantage\" belong to the ownership forms, not the plan. The count is "},{"text":"8","bold":true},{"text":", not 6, 7 or 10."}]}]}]},{"number":"4.2","title":"Case study: Swift Clean","mustKnow":[{"type":"paragraph","text":[{"text":"Swift Clean:","bold":true},{"text":" a "},{"text":"Lagos-based","bold":true},{"text":" idea, a "},{"text":"Mobile Laundry Service Startup","bold":true},{"text":". Its plan runs in "},{"text":"7 stages","bold":true},{"text":":"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Business Idea:","bold":true},{"text":" on-demand laundry "},{"text":"pickup and delivery via an app","bold":true},{"text":" for students in "},{"text":"Akoka and Yaba","bold":true},{"text":"."}]},{"text":[{"text":"Problem & Solution:","bold":true},{"text":" students "},{"text":"waste time and money on unreliable laundry services","bold":true},{"text":". Swift Clean offers "},{"text":"scheduled pickups","bold":true},{"text":", "},{"text":"transparent pricing","bold":true},{"text":" and "},{"text":"48-hour turnaround","bold":true},{"text":"."}]},{"text":[{"text":"Target Market:","bold":true},{"text":" "},{"text":"15,000+ undergraduate students","bold":true},{"text":" in "},{"text":"UNILAG and YabaTech hostels","bold":true},{"text":"."}]},{"text":[{"text":"USP:","bold":true},{"text":" "},{"text":"student-friendly pricing","bold":true},{"text":", "},{"text":"free pickup/delivery on campus","bold":true},{"text":", and a "},{"text":"loyalty points system","bold":true},{"text":"."}]},{"text":[{"text":"Go-to-Market:","bold":true},{"text":" "},{"text":"campus ambassador programme","bold":true},{"text":", "},{"text":"targeted Instagram/Facebook ads","bold":true},{"text":", "},{"text":"partnerships with student associations","bold":true},{"text":"."}]},{"text":[{"text":"Revenue Model:","bold":true},{"text":" "},{"text":"per-kg pricing","bold":true},{"text":", with discounted monthly "},{"text":"\"bulk\" plans for hostels and couples","bold":true},{"text":"."}]},{"text":[{"text":"Milestones (First 90 Days):","bold":true},{"text":" "},{"text":"launch app","bold":true},{"text":", "},{"text":"onboard 200 customers","bold":true},{"text":", "},{"text":"secure 1 hostel partnership","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The stages are shown on a horizontal dashed timeline, with Stages 1, 3, 5 and 7 below the line and Stages 2, 4 and 6 above it."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Swift Clean shows how a simple idea becomes a plan step by step: start with the idea, name the problem and your answer to it, say who your customers are and how many, say why they should choose you, how $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 15, $study_guide$you will reach them, how you will make money, and what you will achieve first."}]},{"text":[{"text":"USP","bold":true},{"text":" (unique selling proposition) is what makes Swift Clean special to the customer: cheap for students, free campus pickup and delivery, loyalty points. "},{"text":"Go-to-Market","bold":true},{"text":" is how it reaches customers: ambassadors, social media ads, student associations. Exams love swapping these two. Free pickup/delivery is USP, not Go-to-Market; the campus ambassador programme is Go-to-Market, not USP and not part of Problem & Solution."}]},{"text":[{"text":"Problem & Solution","bold":true},{"text":" contains exactly three offers: scheduled pickups, transparent pricing, 48-hour turnaround."}]},{"text":[{"text":"Numbers to protect:","bold":true},{"text":" "},{"text":"48","bold":true},{"text":" hours (not 24 or 72), "},{"text":"15,000+","bold":true},{"text":" students (not 1,500 or 50,000), "},{"text":"200","bold":true},{"text":" customers (not 2,000 or 15,000), "},{"text":"1","bold":true},{"text":" hostel partnership (not 10), "},{"text":"90","bold":true},{"text":" days (not 30 days, 6 months or a year), "},{"text":"7","bold":true},{"text":" stages."}]},{"text":[{"text":"Places to protect:","bold":true},{"text":" the idea is for students in "},{"text":"Akoka and Yaba","bold":true},{"text":"; the target market is "},{"text":"UNILAG and YabaTech","bold":true},{"text":" hostels (not LASU or UNIBEN). It is Lagos-based and a laundry service, not food delivery or hostel booking."}]},{"text":[{"text":"Revenue is "},{"text":"per kg","bold":true},{"text":", not per item, per hour or a flat yearly fee; the discounted "},{"text":"monthly bulk plans","bold":true},{"text":" are for "},{"text":"hostels and couples","bold":true},{"text":"."}]},{"text":[{"text":"Order to remember: Idea, Problem, Market, USP, Go-to-Market, Revenue, Milestones. So the stage after Target Market (3) is USP (4); Go-to-Market is Stage 5; the first is Business Idea; the last is Milestones."}]},{"text":[{"text":"Note that Stage 6 of the case (Revenue Model) is also one of the 8 core components, but the case has no \"Executive Summary\" stage."}]}]}]},{"number":"4.3","title":"Sole proprietorship and general partnership","mustKnow":[{"type":"paragraph","text":[{"text":"Sole proprietorship","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A "},{"text":"single owner","bold":true},{"text":" with "},{"text":"no legal difference between the owner and the business","bold":true},{"text":": the owner has "},{"text":"total control","bold":true},{"text":", "},{"text":"keeps all profits","bold":true},{"text":", but also has "},{"text":"unlimited personal liability","bold":true},{"text":" for all debts and losses."}]},{"text":[{"text":"It is "},{"text":"simple to register","bold":true},{"text":" and is often called a "},{"text":"'Business Name'","bold":true},{"text":"."}]},{"text":[{"text":"\"Someone who owns an "},{"text":"unincorporated business by himself or herself","bold":true},{"text":" is a sole proprietor\" "},{"text":"(Tyler, 2025)","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"General partnership","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A business arrangement by which "},{"text":"two or more individuals","bold":true},{"text":" agree to "},{"text":"share responsibilities, assets, profits, and financial and legal liabilities","bold":true},{"text":" associated with a jointly-owned business "},{"text":"(Bloomenthal, 2025)","bold":true},{"text":"."}]},{"text":[{"text":"Less expensive to form than a corporation","bold":true},{"text":"; common for "},{"text":"small, trusted teams","bold":true},{"text":" (e.g., a "},{"text":"boutique firm run by spouses","bold":true},{"text":")."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The sole proprietor "},{"text":"is","bold":true},{"text":" the business in the eyes of the law. That is why the owner enjoys everything (control, all the profit) and also carries everything (all the debts). If Mama Nkechi runs her provision shop in Mushin alone under a business name and a supplier can claim against her personal property for a shop debt, she is a sole proprietor. The picture of a smiling market vendor beside a \"RISK\" gauge sums it up: simple and yours, but risky."}]},{"text":[{"text":"\"Business Name\" is the everyday label for a sole proprietorship; do not confuse it with \"Limited Company\" or \"Cooperative Society\"."}]},{"text":[{"text":"A sole proprietorship is "},{"text":"not","bold":true},{"text":" a distinct legal entity and does "},{"text":"not","bold":true},{"text":" have perpetual existence; those are features of the LLP (Lesson 4.4)."}]},{"text":[{"text":"Tyler (2025)","bold":true},{"text":" goes with the sole proprietor; the key word in his line is "},{"text":"unincorporated","bold":true},{"text":"."}]},{"text":[{"text":"A general partnership is like two friends who open a phone accessories shop together and share the work, the money and the debts. "},{"text":"Bloomenthal (2025)","bold":true},{"text":" goes with the general partnership. The key word is "},{"text":"share","bold":true},{"text":": responsibilities, assets, profits and liabilities, including legal and financial ones."}]},{"text":[{"text":"Compared with a corporation it is "},{"text":"cheaper","bold":true},{"text":" to form (not more expensive), and there is no rule requiring investors or a minimum of ten partners."}]},{"text":[{"text":"The example is a "},{"text":"boutique firm run by spouses","bold":true},{"text":". Do not mix it up with the LLP example (law, accounting, consulting) or the cooperative example (farmers pooling resources)."}]}]}]},{"number":"4.4","title":"Limited liability partnership and cooperative","mustKnow":[{"type":"paragraph","text":[{"text":"Limited Liability Partnership (LLP)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A busine$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 16, $study_guide$ss structure "},{"text":"blending features of partnerships and corporations","bold":true},{"text":", offering partners "},{"text":"limited personal liability","bold":true},{"text":" for business debts and obligations, "},{"text":"protecting their personal assets from business failures or co-partners' misconduct","bold":true},{"text":", while allowing "},{"text":"flexibility in management","bold":true},{"text":" "},{"text":"(Beattie, 2025)","bold":true},{"text":"."}]},{"text":[{"text":"It is a "},{"text":"distinct legal entity","bold":true},{"text":" with "},{"text":"perpetual existence","bold":true},{"text":", "},{"text":"separate from its members","bold":true},{"text":", enabling it to "},{"text":"own property, sue, and be sued","bold":true},{"text":"."}]},{"text":[{"text":"Ideal for "},{"text":"professional services","bold":true},{"text":" like "},{"text":"law, accounting, or consulting","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Cooperative (co-op)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"A business "},{"text":"owned and democratically controlled by its members","bold":true},{"text":", who are also its "},{"text":"customers, workers, or producers","bold":true},{"text":" "},{"text":"(Lip, 2024)","bold":true},{"text":"."}]},{"text":[{"text":"Focus: meeting "},{"text":"shared economic, social, and cultural needs rather than just profit","bold":true},{"text":"."}]},{"text":[{"text":"Profits are often "},{"text":"returned as patronage refunds","bold":true},{"text":" or "},{"text":"reinvested for member benefit","bold":true},{"text":"."}]},{"text":[{"text":"Key features (4):","bold":true},{"text":" voluntary membership; equal voting rights ("},{"text":"one member, one vote","bold":true},{"text":"); collective management; mutual benefit."}]},{"text":[{"text":"Differs from traditional corporations, where "},{"text":"control is based on share ownership","bold":true},{"text":"."}]},{"text":[{"text":"Types (3):","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Consumer","bold":true},{"text":" co-op (grocery)."}]},{"text":[{"text":"Worker","bold":true},{"text":" co-op (employee-owned)."}]},{"text":[{"text":"Producer","bold":true},{"text":" co-op (farmers pooling resources)."}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The LLP sits between a partnership and a corporation: partners run it flexibly like a partnership, but the business stands on its own like a corporation. Because it is a "},{"text":"separate legal entity","bold":true},{"text":", it can own property and be sued in its own name, and it continues even if members change (perpetual existence)."}]},{"text":[{"text":"Limited","bold":true},{"text":" liability is the heart of it: if the firm fails, or a co-partner misbehaves, the other partners' personal assets are protected. An option saying LLP partners have "},{"text":"unlimited","bold":true},{"text":" liability is false. The protection is from business failures or co-partners' misconduct, not from taxes, competition or government regulation."}]},{"text":[{"text":"Three chartered accountants who want protection from each other's misconduct and want the firm to own property in its own name should choose an "},{"text":"LLP","bold":true},{"text":"."}]},{"text":[{"text":"Beattie (2025)","bold":true},{"text":" goes with the LLP. Memory hook: the four ownership citations are "},{"text":"T","bold":true},{"text":"yler (sole), "},{"text":"B","bold":true},{"text":"eattie (LLP), "},{"text":"B","bold":true},{"text":"loomenthal (general partnership), "},{"text":"L","bold":true},{"text":"ip (cooperative, the only 2024 one)."}]},{"text":[{"text":"The cooperative's members are the very people it serves: shoppers, workers or producers. Control is "},{"text":"democratic","bold":true},{"text":", one member one vote, no matter how much money each puts in. \"Control based on share ownership\" is the opposite of a co-op; it describes traditional corporations."}]},{"text":[{"text":"Patronage refund","bold":true},{"text":" means profit given back to members; it belongs to cooperatives only."}]},{"text":[{"text":"Match the type to the members:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Shoppers own the grocery store = "},{"text":"consumer","bold":true},{"text":" co-op."}]},{"text":[{"text":"Employees own the bakery in Ibadan and each has an equal vote = "},{"text":"worker","bold":true},{"text":" co-op."}]},{"text":[{"text":"Rice farmers in Kebbi pool money to buy a shared milling machine and sell together, one vote each = "},{"text":"producer","bold":true},{"text":" co-op."}]}]}]},{"text":[{"text":"A co-op is not about maximising profit for one owner, protecting professional partners, or attracting outside investors to scale; it exists to meet members' shared economic, social and cultural needs."}]}]}]},{"number":"4.5","title":"Comparing forms of business ownership","mustKnow":[{"type":"table","header":[[{"text":"Form of ownership"}],[{"text":"Liability"}],[{"text":"Key disadvantage"}],[{"text":"Best for"}],[{"text":"Key advantage"}]],"rows":[[[{"text":"Sole Proprietorship"}],[{"text":"Unlimited (owner is the business)"}],[{"text":"Personal risk, hard to raise capital"}],[{"text":"Solo vendors, freelancers"}],[{"text":"Simple, low cost, full control"}]],[[{"text":"General Partnership"}],[{"text":"Unlimited (partners are jointly liable)"}],[{"text":"Potential for conflict, shared personal risk"}],[{"text":"Small teams with high trust (e.g., family business)"}],[{"text":"Shared skills/resources, easy to form"}]],[[{"text":"Limited Liability Co. (Ltd)"}],[{"text":"Limited (to shares owned)"}],[{"text":"More complex/expensive to register and run"}],[{"text":"Most scalable startups, any business seeking investment"}],[{"text":"Protects personal assets, credible for investors"}]],[[{"text":"Cooperative"}],[{"text":"Varies"}],[{"text":"Can be slow to decide$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 17, $study_guide$"}],[{"text":"Agricultural groups, credit unions, collective retail"}],[{"text":"Member-owned, democratic control"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The table compares "},{"text":"four","bold":true},{"text":" forms: sole proprietorship, general partnership, limited liability company (Ltd) and cooperative. Note that the "},{"text":"Ltd","bold":true},{"text":" (limited liability company) appears here; it is not the same as the LLP from Lesson 4.4, so read options carefully."}]},{"text":[{"text":"Liability:","bold":true},{"text":" the two "},{"text":"unlimited","bold":true},{"text":" forms are "},{"text":"sole proprietorship","bold":true},{"text":" and "},{"text":"general partnership","bold":true},{"text":". The difference is the reason: for the sole proprietor, \"owner is the business\"; for the partnership, \"partners are jointly liable\". "},{"text":"Ltd","bold":true},{"text":" is limited "},{"text":"to shares owned","bold":true},{"text":". "},{"text":"Cooperative","bold":true},{"text":" liability "},{"text":"varies","bold":true},{"text":"."}]},{"text":[{"text":"Key disadvantages","bold":true},{"text":" line up with each form's nature:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"One person carries everything, so sole proprietorship = "},{"text":"personal risk, hard to raise capital","bold":true},{"text":"."}]},{"text":[{"text":"People share decisions and debts, so general partnership = "},{"text":"potential for conflict, shared personal risk","bold":true},{"text":"."}]},{"text":[{"text":"Ltd has more rules, so = "},{"text":"more complex/expensive to register and run","bold":true},{"text":"."}]},{"text":[{"text":"Everyone votes, so cooperative = "},{"text":"can be slow to decide","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Best for:","bold":true},{"text":" solo vendors and freelancers (sole); small high-trust teams such as a family business (general partnership); scalable startups and businesses seeking investment (Ltd); agricultural groups, credit unions, collective retail (cooperative)."}]},{"text":[{"text":"Key advantages:","bold":true},{"text":" simple, low cost, full control (sole); shared skills/resources, easy to form (general partnership); protects personal assets, credible for investors (Ltd); member-owned, democratic control (cooperative)."}]},{"text":[{"text":"Scenario: Zainab is starting a fintech in Lagos, wants to scale by raising money from investors, and wants her personal assets protected. Choose the "},{"text":"Ltd","bold":true},{"text":", because it is best for scalable startups seeking investment and protects personal assets."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"3 outcomes: identify ownership forms in Nigeria, evaluate their advantages and disadvantages, develop a simple business plan outline."}]},{"text":[{"text":"Business plan = strategic roadmap of goals and methods (Bank of America, 2025); not just for investors; start with a brief mini plan, not 50 pages."}]},{"text":[{"text":"8 components: Executive Summary, Company Description, Business Opportunity, Competitor Analysis, SWOT, Revenue Model, Financial Projection, Team."}]},{"text":[{"text":"Swift Clean: 7 stages; Akoka and Yaba; 48-hour turnaround; 15,000+ UNILAG and YabaTech students; per-kg pricing; 200 customers and 1 hostel partnership in 90 days."}]},{"text":[{"text":"Sole proprietorship (Tyler, 2025): one owner, \"Business Name\", unlimited liability."}]},{"text":[{"text":"General partnership (Bloomenthal, 2025): two or more share everything; cheaper than a corporation; spouses' boutique firm."}]},{"text":[{"text":"LLP (Beattie, 2025): limited liability, separate legal entity, perpetual existence; law, accounting, consulting."}]},{"text":[{"text":"Cooperative (Lip, 2024): member-owned, one member one vote, patronage refunds; consumer, worker, producer types."}]},{"text":[{"text":"Table: sole and general partnership unlimited; Ltd limited to shares; co-op varies and can be slow to decide."}]}]}],"theory":{"itemId":"9a9855b4-670a-571e-943f-42692c7f6c8f","question":[{"type":"paragraph","text":[{"text":"List the core components of a simple business plan and state what each one covers."}]}]},"practice":[{"topic":"Weeks 6-7: Enterprise Formation (Business Plan)","named":false}]}},{"kind":"note","itemId":"88be0c78-731c-502a-a698-aeebca3400cf","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Business Registration and Collaboration","body":"The three learning outcomes; registration as a legal requirement within 28 days and its benefits; CAC, CAMA and the iCRP Portal; the 4 registration steps in order plus the post-registration TIN from FIRS; the 4 pitfalls with their consequences and fixes; partnership, strategic alliance (Wintel), joint venture and networking; the comparison table; the simple 4-step networking plan.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The three learning outcomes; registration as a legal requirement within 28 days and its benefits; CAC, CAMA and the iCRP Portal; the 4 registration steps in order plus the post-registration TIN from FIRS; the 4 pitfalls with their consequences and fixes; partnership, strategic alliance (Wintel), joint venture and networking; the comparison table; the simple 4-step networking plan."}],"lessons":[{"number":"5.1","title":"Business registration in Nigeria and why it matters","mustKnow":[{"type":"paragraph","text":[{"text":"This topic (Weeks 8 and 9, Business Registration) has "},{"text":"3 learning outcomes","bold":true},{"text":". By the end you should be able to:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Understand what "},{"text":"business registration","bold":true},{"text":" means."}]},{"text":[{"text":"Understand the "},{"text":"process","bold":true},{"text":" of business registration."}]},{"text":[{"text":"Know the "},{"text":"common pitfalls","bold":true},{"text":" to avoid."}]}]},{"type"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 18, $study_guide$:"list","ordered":false,"items":[{"text":[{"text":"Registering your business is a "},{"text":"legal requirement within 28 days of starting","bold":true},{"text":"."}]},{"text":[{"text":"Registration:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"gives your business a "},{"text":"legal identity","bold":true},{"text":","}]},{"text":[{"text":"protects your name","bold":true},{"text":","}]},{"text":[{"text":"builds trust","bold":true},{"text":" with customers and banks,"}]},{"text":[{"text":"is "},{"text":"essential for government contracts","bold":true},{"text":","}]},{"text":[{"text":"is "},{"text":"needed to open a corporate bank account","bold":true},{"text":"."}]}]}]}]},{"type":"paragraph","text":[{"text":"The benefits are often shown as "},{"text":"4 labelled icons","bold":true},{"text":":"}]},{"type":"table","header":[[{"text":"Icon label"}],[{"text":"Picture"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Name Protection"}],[{"text":"Padlock on stacked layers"}],[{"text":"Your business name is locked to you"}]],[[{"text":"Legal Identity"}],[{"text":"Gavel on documents"}],[{"text":"The business exists in law"}]],[[{"text":"Trust Building"}],[{"text":"Two businessmen shaking hands beside a document"}],[{"text":"Customers and banks see you as credible"}]],[[{"text":"Contracts"}],[{"text":"A signed \"CONTRACT\" document"}],[{"text":"You can take on government contracts"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Registration is "},{"text":"not optional","bold":true},{"text":" and not something you do \"when the business grows\". The law expects it within "},{"text":"28 days","bold":true},{"text":" of starting. Watch for wrong numbers in options: 14, 30 or 90 days are all traps. The answer is "},{"text":"28","bold":true},{"text":"."}]},{"text":[{"text":"Match each benefit to a situation. If Tola registers \"Tola's Kitchen\" so nobody else can trade under that name, that is "},{"text":"name protection","bold":true},{"text":". If a Surulere tailor's customers and bank start to see the business as more reliable after registration, that is "},{"text":"trust building","bold":true},{"text":". If a business wants to bid for a government job, it needs registration because it is "},{"text":"essential for government contracts","bold":true},{"text":". If it wants a "},{"text":"corporate","bold":true},{"text":" (business) bank account, it needs registration; a personal savings account is not what is meant."}]},{"text":[{"text":"Registration does "},{"text":"not","bold":true},{"text":" excuse you from tax. In fact, tax registration comes straight after it (Lesson 5.2). Any option saying registration \"exempts the business from tax registration\" is false."}]}]}]},{"number":"5.2","title":"The registration process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"In Nigeria, business registration is managed by the "},{"text":"Corporate Affairs Commission (CAC)","bold":true},{"text":" under the "},{"text":"Companies and Allied Matters Act (CAMA)","bold":true},{"text":"."}]},{"text":[{"text":"As of "},{"text":"2026","bold":true},{"text":", the process is primarily completed "},{"text":"online","bold":true},{"text":" through the "},{"text":"iCRP Portal","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The 4 steps, in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Choose and Reserve a Name:","bold":true},{"text":" have "},{"text":"2 alternative names","bold":true},{"text":". Check for and reserve an available name on the "},{"text":"CAC portal","bold":true},{"text":"."}]},{"text":[{"text":"Complete Pre-Registration Form (CAC-BN01):","bold":true},{"text":" submit details "},{"text":"online","bold":true},{"text":": "},{"text":"business activity","bold":true},{"text":" and "},{"text":"proprietor/partner details","bold":true},{"text":" ("},{"text":"NIN","bold":true},{"text":", address, photo)."}]},{"text":[{"text":"Pay Filing Fees:","bold":true},{"text":" pay the prescribed fees "},{"text":"online","bold":true},{"text":"."}]},{"text":[{"text":"Submit and Await Approval:","bold":true},{"text":" "},{"text":"CAC","bold":true},{"text":" processes the application. If approved, you download your "},{"text":"electronic Certificate of Registration","bold":true},{"text":" and "},{"text":"Certified Extract","bold":true},{"text":"."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Post-Registration:","bold":true},{"text":" you must then obtain a "},{"text":"Tax Identification Number (TIN)","bold":true},{"text":" from the "},{"text":"Federal Inland Revenue Service (FIRS)","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Keep the two bodies apart. "},{"text":"CAC","bold":true},{"text":" registers the business (under "},{"text":"CAMA","bold":true},{"text":"). "},{"text":"FIRS","bold":true},{"text":" issues the "},{"text":"TIN","bold":true},{"text":". A common trap swaps them, or brings in other bodies such as SMEDAN or CBN; neither of those manages registration in this topic."}]},{"text":[{"text":"Keep the law apart from the portal: "},{"text":"CAMA","bold":true},{"text":" is the Act; the "},{"text":"iCRP Portal","bold":true},{"text":" is the online platform. An NIN enrolment portal or a \"FIRS TIN portal\" is not the registration platform."}]},{"text":[{"text":"Memory aid for the order: "},{"text":"Name, Form, Fees, Submit","bold":true},{"text":" (then TIN). You cannot fill a form for a business that has no name yet, and you cannot submit before you pay."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Straight after the form (step 2) comes "},{"text":"paying the fees","bold":true},{"text":" (step 3), not submission."}]},{"text":[{"text":"The "},{"text":"first","bold":true},{"text":" step is always choosing and reserving a name."}]}]}]},{"text":[{"text":"Count the alternatives: "},{"text":"2","bold$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 19, $study_guide$":true},{"text":" alternative names, not 1, 3 or 5. They are your backups if your first choice is taken."}]},{"text":[{"text":"The form's code is "},{"text":"CAC-BN01","bold":true},{"text":". Do not accept look-alikes such as CAC-BN02 or CAMA-01. Notice what the form asks for: business activity plus the proprietor's or partners' "},{"text":"NIN","bold":true},{"text":", address and photo. It does "},{"text":"not","bold":true},{"text":" ask for a business plan, bank statements, audited accounts or the TIN (the TIN comes later)."}]},{"text":[{"text":"Two documents arrive at approval: the "},{"text":"electronic Certificate of Registration","bold":true},{"text":" and the "},{"text":"Certified Extract","bold":true},{"text":". A TIN or tax clearance certificate is not part of this download."}]},{"text":[{"text":"The TIN is a "},{"text":"post-registration","bold":true},{"text":" step: it happens after approval, not during name reservation or form filling. So if Femi has just downloaded his Certificate of Registration, his next move is to get a "},{"text":"TIN from FIRS","bold":true},{"text":"."}]},{"text":[{"text":"\"Identify venues\" belongs to the networking plan (Lesson 5.6), not to registration. Exams like to slip it into a list of registration steps."}]}]}]},{"number":"5.3","title":"Common registration pitfalls to avoid","mustKnow":[{"type":"paragraph","text":[{"text":"There are "},{"text":"4 \"Don'ts\"","bold":true},{"text":", each with a consequence and a matching "},{"text":"\"Do\"","bold":true},{"text":":"}]},{"type":"table","header":[[{"text":"Don't"}],[{"text":"Consequence"}],[{"text":"Do"}]],"rows":[[[{"text":"Skip the Name Search"}],[{"text":"Conflicting names cause "},{"text":"rejection","bold":true}],[{"text":"Conduct a "},{"text":"thorough search","bold":true},{"text":" and "},{"text":"have backups","bold":true}]],[[{"text":"Provide Inaccurate Information"}],[{"text":"Errors in documents cause "},{"text":"delays","bold":true}],[{"text":"Double-check","bold":true},{"text":" all names, addresses and NIN details"}]],[[{"text":"Forget Tax Registration"}],[{"text":"It leads to "},{"text":"penalties","bold":true}],[{"text":"Proceed to "},{"text":"FIRS","bold":true},{"text":" for your TIN "},{"text":"immediately after CAC registration","bold":true}]],[[{"text":"Miss Deadlines"}],[{"text":"You pay a "},{"text":"default fee","bold":true},{"text":" after the "},{"text":"28-day grace period","bold":true}],[{"text":"Register as soon as you decide","bold":true},{"text":" to start the business"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Consider Professional Help:","bold":true},{"text":" for "},{"text":"companies (Ltd)","bold":true},{"text":", using a "},{"text":"CAC-accredited agent","bold":true},{"text":" can prevent costly mistakes."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learn each pitfall as a chain: "},{"text":"mistake, result, cure","bold":true},{"text":". Exams swap the results, so fix them firmly:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"name search skipped = "},{"text":"rejection","bold":true},{"text":";"}]},{"text":[{"text":"wrong information = "},{"text":"delays","bold":true},{"text":";"}]},{"text":[{"text":"no tax registration = "},{"text":"penalties","bold":true},{"text":";"}]},{"text":[{"text":"missed deadline = "},{"text":"default fee","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Scenarios: Bisi's \"Bisi Foods\" is rejected because a business already uses a very similar name: she "},{"text":"skipped the name search","bold":true},{"text":". Kunle's application is stuck for weeks because the address on his papers does not match his NIN record: he "},{"text":"provided inaccurate information","bold":true},{"text":"."}]},{"text":[{"text":"The \"Do\" for the name search (thorough search plus backups) links back to step 1's "},{"text":"2 alternative names","bold":true},{"text":"."}]},{"text":[{"text":"The tax \"Do\" says "},{"text":"immediately after CAC registration","bold":true},{"text":", not before reserving a name, not after a year of trading and not only when chasing a contract."}]},{"text":[{"text":"The deadline \"Do\" is to register "},{"text":"as soon as you decide","bold":true},{"text":" to start, not to wait until the grace period ends or until your first profit. The "},{"text":"28-day","bold":true},{"text":" figure is the same one from Lesson 5.1, now called the grace period."}]},{"text":[{"text":"The CAC-accredited agent is recommended for "},{"text":"companies (Ltd)","bold":true},{"text":"; the point is to prevent costly mistakes. It is not recommended \"for every business name\", and it has nothing to do with alliances or networking groups."}]},{"text":[{"text":"\"Failing to join a strategic alliance\" is not a registration pitfall; it is a distractor from the collaboration lessons."}]}]}]},{"number":"5.4","title":"Forms of business collaboration","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" a "},{"text":"formal","bold":true},{"text":" business arrangement where "},{"text":"two or more parties","bold":true},{"text":" combine resources and share "},{"text":"management responsibilities, profits and liabilities","bold":true},{"text":" for an "},{"text":"ongoing","bold":true},{"text":" business. The partners operate the business with a common view of "},{"text":"making a profit","bold":true},{"text":"."}]},{"text":[{"text":"Strategic Alliance:","bold":true},{"text":" a collaborative agreement between "},{"text":"two or more independent organisations","bold":true},{"text":" to pursue "},{"text":"mutually beneficial goals","bold":true},{"text":" while "},{"text":"maintaining their autonomy","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Generally "},{"text":"more flexible and less integrated","bold":true},{"text":" than JVs."}]},{"text":[{"text":"Often involves "},{"text":"c$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 20, $study_guide$ontractual agreements for specific activities","bold":true},{"text":" like "},{"text":"joint marketing, research or distribution","bold":true},{"text":", "},{"text":"without creating a new company","bold":true},{"text":"."}]},{"text":[{"text":"Famous example in the tech industry: the "},{"text":"Wintel (Microsoft and Intel)","bold":true},{"text":" alliance."}]}]}]},{"text":[{"text":"Joint Venture (JV):","bold":true},{"text":" a "},{"text":"specific type of strategic alliance","bold":true},{"text":" where the partnering firms create a "},{"text":"new, jointly owned, separate legal entity","bold":true},{"text":" to pursue a "},{"text":"shared, often time-bound, objective","bold":true},{"text":". This structure allows companies to:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"pool significant resources","bold":true},{"text":","}]},{"text":[{"text":"share risks and costs","bold":true},{"text":","}]},{"text":[{"text":"access new markets or technologies","bold":true},{"text":" they couldn't alone,"}]},{"text":[{"text":"with a "},{"text":"clear legal and governance framework","bold":true},{"text":" in place."}]}]}]},{"text":[{"text":"Networking:","bold":true},{"text":" the "},{"text":"informal","bold":true},{"text":" process of building relationships and connections with other professionals or businesses for "},{"text":"potential future collaboration, information exchange and career development","bold":true},{"text":". Unlike the other forms, networking does "},{"text":"not","bold":true},{"text":" involve "},{"text":"formal agreements, shared capital or a common business goal","bold":true},{"text":" at the outset."}]}]},{"type":"paragraph","text":[{"text":"The four forms are often shown with icons: a "},{"text":"handshake","bold":true},{"text":" (Partnership); two people shaking hands under a "},{"text":"dollar coin","bold":true},{"text":" (Strategic Alliance); people fitting together "},{"text":"jigsaw-puzzle pieces","bold":true},{"text":" (Joint Venture); two businessmen shaking hands, one holding a "},{"text":"briefcase","bold":true},{"text":" (Networking)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Spot the key words in each definition:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partnership:","bold":true},{"text":" \"combine resources\", \"share management, profits and liabilities\", \"ongoing\", \"making a profit\"."}]},{"text":[{"text":"Strategic alliance:","bold":true},{"text":" \"independent\", \"maintaining their autonomy\", \"mutually beneficial goals\", \"without creating a new company\"."}]},{"text":[{"text":"Joint venture:","bold":true},{"text":" \"new, jointly owned, separate legal entity\", \"time-bound\"."}]},{"text":[{"text":"Networking:","bold":true},{"text":" \"informal\", \"relationships\", \"information exchange\", \"career development\"."}]}]}]},{"text":[{"text":"A "},{"text":"JV is a type of strategic alliance","bold":true},{"text":", not a type of partnership or networking. The difference is that a JV goes further and "},{"text":"creates a new company","bold":true},{"text":"; an ordinary alliance does not."}]},{"text":[{"text":"Wintel","bold":true},{"text":" = "},{"text":"Microsoft and Intel","bold":true},{"text":", and it is a "},{"text":"strategic alliance","bold":true},{"text":", not a JV. Watch for look-alike pairs such as Microsoft and IBM."}]},{"text":[{"text":"The specific activities of an alliance are joint marketing, research and distribution. \"Creating a new jointly owned company\" is "},{"text":"not","bold":true},{"text":" one of them; that would make it a JV."}]},{"text":[{"text":"The JV's advantages are pooling resources, sharing risks and costs, and reaching new markets or technologies, all "},{"text":"with","bold":true},{"text":" a clear legal and governance framework. An option claiming a JV \"avoids any legal or governance framework\" is false."}]},{"text":[{"text":"Scenarios to practise:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ngozi and Ibrahim pool their savings to run a pharmacy in Ikeja, sharing management, profits and liabilities on an ongoing basis = "},{"text":"partnership","bold":true},{"text":"."}]},{"text":[{"text":"A Lagos fintech and a telecom company sign a contract to jointly market a mobile wallet; both stay independent and no new company is formed = "},{"text":"strategic alliance","bold":true},{"text":"."}]},{"text":[{"text":"Two firms form a brand-new company they jointly own to run one project for a fixed number of years = "},{"text":"joint venture","bold":true},{"text":"."}]},{"text":[{"text":"A student attends tech meetups to meet professionals and swap ideas, with no agreement and no money put in = "},{"text":"networking","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Networking is not about shared capital in a common business. Building relationships, exchanging information and developing your career "},{"text":"are","bold":true},{"text":" features of networking."}]}]}]},{"number":"5.5","title":"Business collaboration compared","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Collaboration can take the form of "},{"text":"partnerships, alliances, joint ventures and networking","bold":true},{"text":", differing primarily in their "},{"text":"formality, legal structure and objectives","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"main distinction","bold":true},{"text":" lies in "},{"text":"whether a new legal entity is formed","bold":true},{"text":" and the "},{"text":"level of integration and commitment","bold":true},{"text":" involved."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Strategic Alliance"}],[{"text":"Partnership"}],[{"text":"Joint Venture (JV)"}],[{"text":"Networking"}]],"rows":[[[{"text":"Formality"}],[{"text":"Formal agreement, but looser than a JV"}],[{"text":"Formal, typically long-term"}],[{"text":"Highly formal, contractual agreement"}],[{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 21, $study_guide$ext":"Informal relationship building"}]],[[{"text":"Legal Entity"}],[{"text":"No new entity created; partners remain independent"}],[{"text":"Single entity (two or more persons/companies)"}],[{"text":"Creates a new, separate legal entity, jointly owned"}],[{"text":"No new entity"}]],[[{"text":"Objective"}],[{"text":"Specific, mutually beneficial goals (e.g. R&D, marketing)"}],[{"text":"Ongoing general business for profit"}],[{"text":"Single, specific project or objective"}],[{"text":"Information exchange, relationship building, future opportunities"}]],[[{"text":"Risk/Control"}],[{"text":"Greater flexibility, less control/commitment than a JV"}],[{"text":"Shared management and liability"}],[{"text":"Pooled resources and shared risks/costs; shared control"}],[{"text":"Minimal financial risk"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Read the table row by row, because exams pick one cell and ask you to name the form:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Formality","bold":true},{"text":" ladder, from most to least formal: JV (highly formal, contractual) and partnership (formal, typically long-term), then alliance (formal but looser than a JV), then networking (informal)."}]},{"text":[{"text":"Legal entity:","bold":true},{"text":" only the "},{"text":"JV creates a new, separate, jointly owned entity","bold":true},{"text":". The partnership is a "},{"text":"single entity","bold":true},{"text":" made up of two or more persons or companies. The alliance creates "},{"text":"no new entity","bold":true},{"text":" and the partners "},{"text":"remain independent","bold":true},{"text":". Networking creates "},{"text":"no new entity","bold":true},{"text":"."}]},{"text":[{"text":"Objective:","bold":true},{"text":" partnership = "},{"text":"ongoing general business for profit","bold":true},{"text":"; JV = "},{"text":"single, specific project or objective","bold":true},{"text":"; alliance = "},{"text":"specific, mutually beneficial goals","bold":true},{"text":" such as R&D or marketing; networking = "},{"text":"information exchange, relationship building, future opportunities","bold":true},{"text":"."}]},{"text":[{"text":"Risk/control:","bold":true},{"text":" networking carries "},{"text":"minimal financial risk","bold":true},{"text":"; partnership = "},{"text":"shared management and liability","bold":true},{"text":"; alliance = "},{"text":"greater flexibility, less control/commitment than a JV","bold":true},{"text":"; JV = "},{"text":"pooled resources, shared risks/costs, shared control","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Common traps: \"formal, typically long-term\" is the "},{"text":"partnership","bold":true},{"text":", not the JV; \"single, specific project\" is the "},{"text":"JV","bold":true},{"text":", not the partnership; \"no new entity, partners remain independent\" is the "},{"text":"alliance","bold":true},{"text":", while networking's cell simply says \"no new entity\"."}]},{"text":[{"text":"Do not mix in unrelated features. The forms do not differ \"primarily\" by size, location, number of employees, prices or industry; the answer is "},{"text":"formality, legal structure and objectives","bold":true},{"text":"."}]}]}]},{"number":"5.6","title":"A simple 4-step networking plan","mustKnow":[{"type":"paragraph","text":[{"text":"The 4 steps, in order:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Goal:","bold":true},{"text":" "},{"text":"What do you need?","italic":true},{"text":" It could be a "},{"text":"technical co-founder for an app idea","bold":true},{"text":" or "},{"text":"feedback on a product from 10 potential customers","bold":true},{"text":"."}]},{"text":[{"text":"Identify Venues:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Online:","bold":true},{"text":" optimise your "},{"text":"LinkedIn","bold":true},{"text":". Join groups like "},{"text":"\"Nigeria Tech Community\"","bold":true},{"text":"."}]},{"text":[{"text":"Offline:","bold":true},{"text":" attend events like "},{"text":"Lagos Startup Week","bold":true},{"text":", "},{"text":"Techpoint Build","bold":true},{"text":", or meetups at hubs like "},{"text":"Hub One by FCMB in Yaba","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Engage:","bold":true},{"text":" "},{"text":"don't just collect cards","bold":true},{"text":". "},{"text":"Offer value","bold":true},{"text":", "},{"text":"ask insightful questions","bold":true},{"text":", and "},{"text":"follow up within 48 hours","bold":true},{"text":" with a "},{"text":"personalised message","bold":true},{"text":"."}]},{"text":[{"text":"Maintain:","bold":true},{"text":" "},{"text":"nurture relationships","bold":true},{"text":". "},{"text":"Share useful information","bold":true},{"text":", "},{"text":"make introductions","bold":true},{"text":", and "},{"text":"check in periodically","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The plan is often drawn as four diamond-shaped tiles: "},{"text":"Goal","bold":true},{"text":" at the top (a target/bullseye with an arrow), "},{"text":"Identify Venues","bold":true},{"text":" on the right (a location pin), "},{"text":"Engage","bold":true},{"text":" at the bottom (a handshake with speech bubbles), "},{"text":"Maintain","bold":true},{"text":" on the left (a laptop)."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Memory aid: "},{"text":"G-I-E-M","bold":true},{"text":", \"Get In, Engage, Maintain\". First decide "},{"text":"what","bold":true},{"text":" you need, then "},{"text":"where","bold":true},{"text":" to find the people, then "},{"text":"how","bold":true},{"text":" to connect, then how to "},{"text":"keep","bold":true},{"text":" the connection."}]},{"text":[{"text":"Numbers to know: "},{"text":"10","bold":true},{"text":" potential customers (Goal example) and "},{"text":"48 hours","bold":true},{"text":" (Engage follow-up). Do not confuse 48 hours $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 22, $study_guide$with the "},{"text":"28 days","bold":true},{"text":" of business registration."}]},{"text":[{"text":"Online versus offline: "},{"text":"LinkedIn","bold":true},{"text":" and the "},{"text":"\"Nigeria Tech Community\"","bold":true},{"text":" group are "},{"text":"online","bold":true},{"text":". "},{"text":"Lagos Startup Week","bold":true},{"text":", "},{"text":"Techpoint Build","bold":true},{"text":" and "},{"text":"Hub One by FCMB","bold":true},{"text":" meetups are "},{"text":"offline","bold":true},{"text":". Hub One by FCMB is in "},{"text":"Yaba","bold":true},{"text":", not Lekki, Victoria Island or Ikeja."}]},{"text":[{"text":"Tell Engage from Maintain by timing. "},{"text":"Engage","bold":true},{"text":" is the first contact and the quick follow-up: at Lagos Startup Week, Dayo asks a speaker thoughtful questions, offers to help with her project and sends a personalised message the next day. "},{"text":"Maintain","bold":true},{"text":" is the long run: months after meeting a mentor, Seyi still shares useful articles, introduces her to other founders and checks in now and then."}]},{"text":[{"text":"\"Collecting as many business cards as possible\" is exactly what the plan warns against. \"Choose and reserve a name\" belongs to CAC registration, not to networking."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Registration is a legal requirement within "},{"text":"28 days","bold":true},{"text":" of starting; it gives legal identity, protects your name, builds trust with customers and banks, is essential for government contracts and is needed for a corporate bank account."}]},{"text":[{"text":"CAC","bold":true},{"text":" manages registration under "},{"text":"CAMA","bold":true},{"text":"; as of 2026 it is mainly online through the "},{"text":"iCRP Portal","bold":true},{"text":"."}]},{"text":[{"text":"4 steps: choose and reserve a name (2 alternatives), complete "},{"text":"CAC-BN01","bold":true},{"text":" (business activity, NIN, address, photo), pay filing fees online, submit and await approval (electronic Certificate of Registration and Certified Extract)."}]},{"text":[{"text":"Post-registration: get a "},{"text":"TIN","bold":true},{"text":" from "},{"text":"FIRS","bold":true},{"text":"."}]},{"text":[{"text":"Pitfalls: skipped name search = rejection; inaccurate information = delays; no tax registration = penalties; missed deadline = default fee after the 28-day grace period. Companies (Ltd): consider a CAC-accredited agent."}]},{"text":[{"text":"Partnership = formal, ongoing, shared management, profits and liabilities, for profit."}]},{"text":[{"text":"Strategic alliance = independent firms, mutual goals, autonomy kept, no new company; Wintel (Microsoft and Intel)."}]},{"text":[{"text":"Joint venture = a type of strategic alliance that creates a new, jointly owned, separate legal entity for a shared, often time-bound objective."}]},{"text":[{"text":"Networking = informal relationship building; no formal agreement, shared capital or common goal at the outset; minimal financial risk."}]},{"text":[{"text":"Networking plan: Goal, Identify Venues, Engage (follow up within 48 hours), Maintain."}]}]}],"theory":{"itemId":"a96e4038-68ca-52bd-977d-bce0993a1497","question":[{"type":"paragraph","text":[{"text":"Outline the steps involved in registering a business in Nigeria."}]}]},"practice":[{"topic":"Weeks 8-9: Business Registration and Collaboration","named":false}]}},{"kind":"note","itemId":"f1ee6835-09ed-56e9-97fc-84121bb4ad5c","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Micro and Small Enterprises","body":"The definitions of micro and small enterprise (World Bank 2020, SMEDAN 2017, OECD) with their employee and ₦ asset limits; the 7 characteristics of micro enterprises and the 12 of small enterprises; the categories and types of each, with their examples; the 12-point comparison of micro and small; and the four areas of importance (wealth creation, employment generation, financial independence, poverty reduction) with every point under each.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"The definitions of micro and small enterprise (World Bank 2020, SMEDAN 2017, OECD) with their employee and ₦ asset limits; the 7 characteristics of micro enterprises and the 12 of small enterprises; the categories and types of each, with their examples; the 12-point comparison of micro and small; and the four areas of importance (wealth creation, employment generation, financial independence, poverty reduction) with every point under each."}],"lessons":[{"number":"6.1","title":"Micro enterprise: definition and characteristics","mustKnow":[{"type":"paragraph","text":[{"text":"The aims of this topic: define micro and small enterprise, state their characteristics and identify their community; distinguish between micro and small enterprise; state the role and importance of micro and small businesses in "},{"text":"wealth creation","bold":true},{"text":", "},{"text":"employment","bold":true},{"text":", "},{"text":"financial independence","bold":true},{"text":" and "},{"text":"poverty reduction","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Micro enterprise:","bold":true},{"text":" a very small business operation that employs a "},{"text":"minimal number of people","bold":true},{"text":" and operates with "},{"text":"low capital investment","bold":true},{"text":". It is often "},{"text":"owner-managed","bold":true},{"text":" and may be "},{"text":"informal","bold":true},{"text":" in nature."}]},{"text":[{"text":"World Bank (2020):","bold":true},{"text":" micro enterprises are firms with "},{"text":"fewer than 10 employees","bold":true},{"text":"."}]},{"text":[{"text":"SMEDAN (2017)","bold":true},{"text":", in Nigeria: a micro enterprise is a business with:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"less than 10 employees","bold":true},{"text":", and"}]},{"text":[{"text":"total ass$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 23, $study_guide$ets (excluding land and building) not exceeding ₦5 million","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Picture to remember: a "},{"text":"barber shop","bold":true},{"text":", one barber cutting a seated customer's hair while another customer waits."}]}]},{"type":"paragraph","text":[{"text":"7 characteristics of micro enterprise","bold":true},{"text":" (in order):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Low Start-Up Capital:","bold":true},{"text":" requires minimal financial investment to start and operate."}]},{"text":[{"text":"Limited Use of Technology:","bold":true},{"text":" relies on basic tools and manual processes rather than advanced technology."}]},{"text":[{"text":"Owner-Dependent Operations:","bold":true},{"text":" business success is largely dependent on the owner's skills, effort and decisions."}]},{"text":[{"text":"Restricted Market Coverage:","bold":true},{"text":" serves local or community-based markets rather than national or international markets."}]},{"text":[{"text":"Informal Business Structure:","bold":true},{"text":" often operates without full registration or formal documentation."}]},{"text":[{"text":"Limited Access to Credit:","bold":true},{"text":" faces challenges accessing bank loans due to "},{"text":"lack of collaterals and financial records","bold":true},{"text":"."}]},{"text":[{"text":"High Business Mortality Rate:","bold":true},{"text":" more vulnerable to "},{"text":"economic shocks, inflation and policy changes","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Think of the barber in your area: one shop, a chair or two, clippers and a mirror. He did not need much money to start (low start-up capital), he uses simple tools (limited technology), the shop rises or falls with him (owner-dependent), his customers come from the same street or estate (restricted market), he may never have registered with anyone (informal), the bank will not lend to him because he has no collateral and no proper books (limited credit), and one bad season of rising prices can close him down (high mortality)."}]},{"text":[{"text":"SMEDAN's definition has "},{"text":"two","bold":true},{"text":" conditions joined by \"and\": the staff count "},{"text":"and","bold":true},{"text":" the asset limit. When you calculate assets, "},{"text":"land and building are left out","bold":true},{"text":". Vehicles, machines, cash and stock are not excluded."}]},{"text":[{"text":"Traps on numbers: micro is "},{"text":"fewer than 10","bold":true},{"text":" employees (not fewer than 5, not fewer than 50). The SMEDAN asset ceiling is "},{"text":"₦5 million","bold":true},{"text":" (not ₦10 million, ₦49 million or ₦50 million)."}]},{"text":[{"text":"Traps on citations: the "},{"text":"World Bank (2020)","bold":true},{"text":" gives only the employee count for micro. "},{"text":"SMEDAN (2017)","bold":true},{"text":" gives both the employee count and the ₦5 million asset limit. Both definitions agree on \"fewer than 10\"."}]},{"text":[{"text":"Look-alike terms: \""},{"text":"Low","bold":true},{"text":" Start-Up Capital\" belongs to micro; \""},{"text":"Moderate","bold":true},{"text":" Capital Base\" belongs to small. \""},{"text":"Limited","bold":true},{"text":" Use of Technology\" is micro; \""},{"text":"Use of","bold":true},{"text":" Technology\" is small. \""},{"text":"Restricted","bold":true},{"text":" Market Coverage\" is micro; \""},{"text":"Wider","bold":true},{"text":" Market Coverage\" is small. \""},{"text":"High","bold":true},{"text":" Business Mortality Rate\" is micro; \""},{"text":"Lower","bold":true},{"text":" Business Mortality Rate\" is small. \""},{"text":"Informal","bold":true},{"text":" Business Structure\" is micro; \""},{"text":"Formal","bold":true},{"text":" Business Registration\" is small."}]},{"text":[{"text":"If a question describes a story, match the cause to the characteristic: a shop closing after inflation or a new policy = "},{"text":"High Business Mortality Rate","bold":true},{"text":"; a loan refused for lack of collateral and records = "},{"text":"Limited Access to Credit","bold":true},{"text":"; work stopping because the owner is ill = "},{"text":"Owner-Dependent Operations","bold":true},{"text":"."}]}]}]},{"number":"6.2","title":"Examples and types of micro enterprises","mustKnow":[{"type":"paragraph","text":[{"text":"Examples of micro enterprises: 6 categories, 4 examples each","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Retail and Trading:","bold":true},{"text":" provision stores and neighbourhood mini-shops; phone accessories and gadget sales outlets; POS (point of sale) agency businesses; small-scale online vendors on Instagram, WhatsApp and Facebook."}]},{"text":[{"text":"Food and Beverages:","bold":true},{"text":" local food vendors (bukaterias, roadside food sellers); small bakeries producing bread and pastries; pure water (sachet water production units); small catering and home-based food services."}]},{"text":[{"text":"Service-Based:","bold":true},{"text":" hairdressing salons and barbing shops; fashion designers and tailoring shops; laundry and dry-cleaning outlets; photography and videography."}]},{"text":[{"text":"Manufacturing and Craft:","bold":true},{"text":" local soap and detergent producers; small-scale cosmetic and skincare producers; furniture and carpentry workshops; welding and metal fabrication shops."}]},{"text":[{"text":"ICT and Creative:","bold":true},{"text":" freelance graphic design businesses; social media management services; content creation and digital marketing freelancers; small printing and business centre operators."}]},{"text":[{"text":"Agriculture-Based:","bold":true},{"text":" poultry farms with small stock size; fish farming (catfish and tilapia ponds); vegetable and crop farming enterprises; agro-input retail sellers."}]}]},{"type":"paragraph","text":[{"text":"Types of micro enterprises: 3 types","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 24, $study_guide$d":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Production and Craft:","bold":true},{"text":" shoe making and leather works; furniture carpentry; soap and detergent production; bead making and jewellery; local bakery or snacks production; small-scale tailoring."}]},{"text":[{"text":"Service-oriented:","bold":true},{"text":" hairdressing/barbing salon; laundry and dry cleaning services; mobile phone repairs; car wash businesses; catering and small food vending."}]},{"text":[{"text":"Retail and Trading:","bold":true},{"text":" small grocery or provision stores; roadside fruit and vegetable sellers; cosmetic and beauty products retail; recharge card and SIM card vending; keke/okada small transport business."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"There are two separate lists here. The "},{"text":"examples","bold":true},{"text":" list has "},{"text":"6 categories","bold":true},{"text":" (Retail and Trading, Food and Beverages, Service-Based, Manufacturing and Craft, ICT and Creative, Agriculture-Based). The "},{"text":"types","bold":true},{"text":" list has "},{"text":"3 types","bold":true},{"text":" (Production and Craft, Service-oriented, Retail and Trading). Know which list a question is drawing from by the wording of its options."}]},{"text":[{"text":"Hospitality and Tourism","bold":true},{"text":", "},{"text":"Trade and Commerce","bold":true},{"text":", "},{"text":"Manufacturing-Based","bold":true},{"text":" and "},{"text":"ICT and Digital","bold":true},{"text":" are categories of "},{"text":"small","bold":true},{"text":" enterprises, not micro. If one appears as an option for a micro category, it is the odd one out."}]},{"text":[{"text":"Some placements surprise people, so learn them exactly:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"POS agency","bold":true},{"text":" and "},{"text":"online vendors on Instagram, WhatsApp and Facebook","bold":true},{"text":" are "},{"text":"Retail and Trading","bold":true},{"text":", not ICT and Creative. They are selling or trading."}]},{"text":[{"text":"Pure water (sachet water)","bold":true},{"text":" is "},{"text":"Food and Beverages","bold":true},{"text":", not Manufacturing and Craft."}]},{"text":[{"text":"Photography and videography","bold":true},{"text":" is "},{"text":"Service-Based","bold":true},{"text":"."}]},{"text":[{"text":"Agro-input retail sellers","bold":true},{"text":" sit under "},{"text":"Agriculture-Based","bold":true},{"text":", even though they retail."}]},{"text":[{"text":"Small printing and business centre operators","bold":true},{"text":" are "},{"text":"ICT and Creative","bold":true},{"text":"."}]},{"text":[{"text":"In the types list, "},{"text":"keke/okada small transport","bold":true},{"text":" is under "},{"text":"Retail and Trading","bold":true},{"text":", and "},{"text":"mobile phone repairs","bold":true},{"text":" is under "},{"text":"Service-oriented","bold":true},{"text":"."}]},{"text":[{"text":"Cosmetic and beauty products retail","bold":true},{"text":" (selling products other people made) is "},{"text":"Retail and Trading","bold":true},{"text":"; producing cosmetics yourself is "},{"text":"Manufacturing and Craft","bold":true},{"text":" in the examples list."}]}]}]},{"text":[{"text":"Furniture and carpentry, soap and detergent, and tailoring appear in more than one list; the category tells you what the business does (making things versus selling or serving)."}]}]}]},{"number":"6.3","title":"Small enterprise: definition, characteristics and types","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SMEDAN (2017)","bold":true},{"text":" (Small and Medium Enterprise Development Agency of Nigeria): a small enterprise is an enterprise with "},{"text":"10-49 employees","bold":true},{"text":" and "},{"text":"total assets between ₦5 million and ₦49 million, excluding land and buildings","bold":true},{"text":"."}]},{"text":[{"text":"World Bank (2020):","bold":true},{"text":" a small enterprise is a firm that employs "},{"text":"10-49 people","bold":true},{"text":"."}]},{"text":[{"text":"OECD","bold":true},{"text":" (Organisation for Economic Co-operation and Development): small enterprises are firms that employ "},{"text":"fewer than 50 people","bold":true},{"text":" and "},{"text":"operate with limited resources compared to large firms","bold":true},{"text":"."}]},{"text":[{"text":"Picture to remember: \""},{"text":"Small Business","bold":true},{"text":"\" linked to a vegetable shop, bakery, barbershop, nail salon, pottery and flower shop."}]}]},{"type":"paragraph","text":[{"text":"12 characteristics of small enterprises","bold":true},{"text":" (in order):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Moderate Capital Base"}]},{"text":[{"text":"Formal Business Registration"}]},{"text":[{"text":"Structured Management Systems"}]},{"text":[{"text":"Improved Record-Keeping"}]},{"text":[{"text":"Better Access to Finance"}]},{"text":[{"text":"Wider Market Coverage"}]},{"text":[{"text":"Use of Technology"}]},{"text":[{"text":"Higher Productivity Levels"}]},{"text":[{"text":"Growth and Expansion Orientation"}]},{"text":[{"text":"Employment of Skilled Labour"}]},{"text":[{"text":"Lower Business Mortality Rate"}]},{"text":[{"text":"Compliance with Labour and Tax Laws"}]}]},{"type":"paragraph","text":[{"text":"Types of small enterprises: 6 types","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Manufacturing-Based:","bold":true},{"text":" small-scale food processing companies (e.g. packaged snacks, bread, fruit juice); furniture and carpentry workshops; soap, cosmetic and detergent production companies; garment and textile production companies."}]},{"text":[{"text":"Service-oriented:","bold":true},{"text":" private schools and tutorial centres; small hospitals, clinics and diagnostic centres; accounting, auditing and consulting firms; logistics and courier service$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 25, $study_guide$ companies."}]},{"text":[{"text":"Trade and Commerce:","bold":true},{"text":" wholesale distribution businesses; supermarkets and mini-marts; import and export trading companies; building materials distribution firms."}]},{"text":[{"text":"ICT and Digital:","bold":true},{"text":" software development companies; digital marketing agencies; web design and IT support firms; fintech startups operating on a small scale."}]},{"text":[{"text":"Hospitality and Tourism:","bold":true},{"text":" hotels and guest houses; restaurants and catering services; travel and tour agencies; event management companies."}]},{"text":[{"text":"Agriculture-based:","bold":true},{"text":" commercial farms (poultry, fishery, crop farming); agro-processing firms (rice milling, cassava processing); agricultural input supply companies."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Three definitions, three different emphases. "},{"text":"SMEDAN (2017)","bold":true},{"text":" uses staff "},{"text":"and","bold":true},{"text":" assets (10-49 employees, ₦5 million to ₦49 million, land and buildings excluded). "},{"text":"World Bank (2020)","bold":true},{"text":" uses staff only (10-49). "},{"text":"OECD","bold":true},{"text":" says "},{"text":"fewer than 50","bold":true},{"text":" and adds \""},{"text":"limited resources compared to large firms","bold":true},{"text":"\". If an option mentions limited resources, it is OECD; if it mentions naira, it is SMEDAN."}]},{"text":[{"text":"SMEDAN's full name in this course is the "},{"text":"Small and Medium Enterprise Development Agency of Nigeria","bold":true},{"text":". Distractors swap in \"Micro\", \"Authority\", \"Directorate\" or \"Association\"."}]},{"text":[{"text":"Work out classification questions with both SMEDAN conditions: 4 staff and ₦3 million assets is "},{"text":"micro","bold":true},{"text":"; 25 staff and ₦20 million assets is "},{"text":"small","bold":true},{"text":". Notice that ₦5 million is the line where micro ends and small begins."}]},{"text":[{"text":"The 12 small-enterprise characteristics are mostly the \"grown-up\" versions of the micro ones: it is registered, it has a management structure, it keeps better records, banks are more willing to lend to it, it sells further afield, it uses technology, it is more productive, it plans to grow, it hires skilled people, it survives longer, and it obeys labour and tax law."}]},{"text":[{"text":"Story matching: a firm that registers staff for pension, deducts tax and files returns on time shows "},{"text":"Compliance with Labour and Tax Laws","bold":true},{"text":"; a school with a principal, administrator and heads of department each with clear duties shows "},{"text":"Structured Management Systems","bold":true},{"text":"; a firm that deliberately hires qualified accountants and certified technicians shows "},{"text":"Employment of Skilled Labour","bold":true},{"text":"; a supermarket opening a second branch with plans for more shows "},{"text":"Growth and Expansion Orientation","bold":true},{"text":"."}]},{"text":[{"text":"Owner-Dependent Operations","bold":true},{"text":", "},{"text":"Limited Use of Technology","bold":true},{"text":", "},{"text":"Informal Business Structure","bold":true},{"text":", "},{"text":"Restricted Market Coverage","bold":true},{"text":", "},{"text":"Limited Access to Credit","bold":true},{"text":" and "},{"text":"High Business Mortality Rate","bold":true},{"text":" are "},{"text":"not","bold":true},{"text":" small-enterprise characteristics; they belong to micro."}]},{"text":[{"text":"Food and Beverages","bold":true},{"text":" is a micro category, not one of the six small-enterprise types. Hospitals and clinics, private schools, consulting firms, wholesalers, supermarkets, import/export companies and hotels are "},{"text":"small","bold":true},{"text":" enterprise examples, not micro."}]}]}]},{"number":"6.4","title":"Distinguishing between micro and small enterprises","mustKnow":[{"type":"table","header":[[{"text":"Point"}],[{"text":"Micro enterprises"}],[{"text":"Small enterprises"}]],"rows":[[[{"text":"Employees"}],[{"text":"Less than 10"}],[{"text":"10-49"}]],[[{"text":"Capital investment"}],[{"text":"Moderate capital investment (as listed; elsewhere micro is described as low start-up capital)"}],[{"text":"Moderate capital investment"}]],[[{"text":"Assets (excluding land and buildings)"}],[{"text":"Less than ₦5 million"}],[{"text":"₦5 million-₦49 million"}]],[[{"text":"Ownership"}],[{"text":"Sole proprietorship, often family-owned"}],[{"text":"Sole proprietorship or partnership"}]],[[{"text":"Management"}],[{"text":"Owner-managed with no formal structure"}],[{"text":"Semi-formal management with defined roles"}]],[[{"text":"Registration"}],[{"text":"Mostly informal, limited registration"}],[{"text":"Mostly formal and registered"}]],[[{"text":"Credit"}],[{"text":"Very limited access to bank credit"}],[{"text":"Better access to loans and government support"}]],[[{"text":"Technology"}],[{"text":"Minimal or manual processes"}],[{"text":"Moderate use of technology"}]],[[{"text":"Market"}],[{"text":"Local or neighbourhood markets"}],[{"text":"Local, regional and sometimes national markets"}]],[[{"text":"Growth"}],[{"text":"Limited scalability"}],[{"text":"Higher growth and expansion potential"}]],[[{"text":"Stability"}],[{"text":"High vulnerability to shocks"}],[{"text":"More stable and sustainable"}]],[[{"text":"Records"}],[{"text":"Poor or informal records"}],[{"text":"Basic structured accounting records"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Read the table across: each row is a pair. Exams often swap a pair, for example \"Micro: more stable and sustainable; Small: high vulnerability to shocks\". That is the wrong way round. Micro is "},{"text":"vulnerable","bold":true},{"text":"; small is "},{"text":"more stable and sustainable","bold":true},{"text":"."}]},{"text":[{"text":"Ownership: micro is "},{"text":"sole proprie$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 26, $study_guide$torship, often family-owned","bold":true},{"text":"; small is "},{"text":"sole proprietorship or partnership","bold":true},{"text":". So partnership appears only on the small side."}]},{"text":[{"text":"Management: \"owner-managed with no formal structure\" is micro; \""},{"text":"semi-formal","bold":true},{"text":" management with defined roles\" is small. Note: semi-formal, not fully formal."}]},{"text":[{"text":"\""},{"text":"Moderate use of technology","bold":true},{"text":"\" describes "},{"text":"small","bold":true},{"text":" enterprises; micro uses \"minimal or manual processes\"."}]},{"text":[{"text":"Markets: small enterprises reach \"local, regional and "},{"text":"sometimes","bold":true},{"text":" national\" markets, not mainly international ones."}]},{"text":[{"text":"Credit: small enterprises get better access to "},{"text":"loans and government support","bold":true},{"text":", not \"no need for finance\"."}]},{"text":[{"text":"Records: \"poor or informal records\" is micro; small keeps basic structured accounting records."}]},{"text":[{"text":"On capital, the comparison lists \"moderate capital investment\" on both sides. When a question asks about the micro characteristic on its own, the answer is "},{"text":"Low Start-Up Capital","bold":true},{"text":" (minimal investment to start and operate)."}]}]}]},{"number":"6.5","title":"Importance of micro and small businesses","mustKnow":[{"type":"paragraph","text":[{"text":"Wealth Creation (4)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Enable individuals to generate income through "},{"text":"ownership of productive assets","bold":true},{"text":"."}]},{"text":[{"text":"Support "},{"text":"capital accumulation and reinvestment","bold":true},{"text":" at the household and community levels."}]},{"text":[{"text":"Encourage "},{"text":"entrepreneurship and venture creation","bold":true},{"text":" across various sectors of the economy."}]},{"text":[{"text":"Promote "},{"text":"inclusive economic growth","bold":true},{"text":" by distributing wealth broadly."}]}]},{"type":"paragraph","text":[{"text":"Employment Generation (3)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Major source of job creation","bold":true},{"text":", especially in "},{"text":"developing economies","bold":true},{"text":"."}]},{"text":[{"text":"Absorb "},{"text":"unskilled, semi-skilled and skilled labour","bold":true},{"text":"."}]},{"text":[{"text":"Provide employment opportunities for "},{"text":"youth, women and vulnerable groups","bold":true},{"text":". Reduce "},{"text":"pressure on the public sector and large firms","bold":true},{"text":" to create jobs."}]}]},{"type":"paragraph","text":[{"text":"Financial Independence (4)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Provide "},{"text":"self-employment and income autonomy","bold":true},{"text":"."}]},{"text":[{"text":"Reduce "},{"text":"dependence on salaried employment and government support","bold":true},{"text":"."}]},{"text":[{"text":"Enable individuals to "},{"text":"manage personal and household finances","bold":true},{"text":" independently."}]},{"text":[{"text":"Foster a culture of "},{"text":"savings, investment and financial responsibility","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Poverty Reduction (4)","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Create "},{"text":"livelihood opportunities in rural and urban areas","bold":true},{"text":"."}]},{"text":[{"text":"Increase "},{"text":"household income and purchasing power","bold":true},{"text":"."}]},{"text":[{"text":"Reduce "},{"text":"income inequality","bold":true},{"text":" through inclusive participation in economic activities."}]},{"text":[{"text":"Support "},{"text":"community development","bold":true},{"text":" and improve "},{"text":"living standards","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Four headings, "},{"text":"15 points","bold":true},{"text":" in total (4 + 3 + 4 + 4). Employment Generation is the only heading with three points; its third point carries two ideas (jobs for youth, women and vulnerable groups, and less pressure on government and big firms)."}]},{"text":[{"text":"Use key words to place a point under its heading:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"assets, capital accumulation, reinvestment, venture creation, distributing wealth","bold":true},{"text":" = Wealth Creation."}]},{"text":[{"text":"jobs, labour, youth and women, pressure on the public sector","bold":true},{"text":" = Employment Generation."}]},{"text":[{"text":"self-employment, autonomy, not depending on salary or government, managing your own finances, savings culture","bold":true},{"text":" = Financial Independence."}]},{"text":[{"text":"livelihoods, household income and purchasing power, income inequality, community development, living standards","bold":true},{"text":" = Poverty Reduction."}]}]}]},{"text":[{"text":"Traps between look-alikes: \""},{"text":"inclusive economic growth","bold":true},{"text":" by distributing wealth broadly\" is "},{"text":"Wealth Creation","bold":true},{"text":", while \"reduce income inequality through "},{"text":"inclusive participation","bold":true},{"text":"\" is "},{"text":"Poverty Reduction","bold":true},{"text":". \"Generate "},{"text":"income","bold":true},{"text":" through ownership of productive assets\" is Wealth Creation, while \"increase "},{"text":"household income","bold":true},{"text":" and purchasing power\" is Poverty Reduction. \"Self-employment\" is Financial Independence, not Employment Generation."}]},{"text":[{"text":"Job creation is described as most important in "},{"text":"developing","bold":true},{"text":" economies, not developed ones."}]},{"text":[{"text":"Everyday illustration: a graduate who starts a catering business so she does$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 27, $study_guide$ not rely on a salaried job or government support, and runs her own household finances, shows "},{"text":"Financial Independence","bold":true},{"text":". Several cassava-processing businesses in a village raising family income, supporting community projects and improving living standards show "},{"text":"Poverty Reduction","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Micro enterprise: very small, minimal staff, low capital, often owner-managed and informal."}]},{"text":[{"text":"World Bank (2020): micro = fewer than 10 employees; small = 10-49 people."}]},{"text":[{"text":"SMEDAN (2017): micro = less than 10 employees and assets not above ₦5 million; small = 10-49 employees and assets ₦5 million-₦49 million; land and buildings excluded."}]},{"text":[{"text":"OECD: small = fewer than 50 people, limited resources compared to large firms."}]},{"text":[{"text":"Micro has 7 characteristics (low capital to high mortality); small has 12 (moderate capital base to compliance with labour and tax laws)."}]},{"text":[{"text":"Micro examples: 6 categories; micro types: 3 (Production and Craft, Service-oriented, Retail and Trading); small types: 6 (Manufacturing, Service, Trade and Commerce, ICT and Digital, Hospitality and Tourism, Agriculture)."}]},{"text":[{"text":"Comparison: micro is family-owned, informal, vulnerable, local; small is sole proprietorship or partnership, semi-formal, registered, more stable, wider markets."}]},{"text":[{"text":"Importance: wealth creation (4), employment generation (3), financial independence (4), poverty reduction (4)."}]}]}],"theory":{"itemId":"add74835-1e5a-5023-bd76-43e46ad48e9b","question":[{"type":"paragraph","text":[{"text":"Using SMEDAN (2017), distinguish between a micro enterprise and a small enterprise, and state two ways micro and small businesses contribute to employment generation."}]}]},"practice":[{"topic":"Weeks 10-11: Micro and Small Enterprises","named":false}]}},{"kind":"note","itemId":"81c9c0ee-873f-53c5-be28-d424d5ff1b04","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Contemporary Issues in Entrepreneurship","body":"The three learning outcomes; knowledge (definition, tacit and explicit, the 4 types of entrepreneurial knowledge); entrepreneurial skills (2 definitions, 9 types); the 10 roles of knowledge and skills; digital entrepreneurship and its 5 kinds of digital business; digital technologies and the 6 groups of digital tools; the 6 impacts of digital technology; the virtual office (features, tools, 5 importances); online networking (3 definitions, 5 importances); e-commerce (3 definitions, 6 types, 8 strategies, 10 opportunities).","noteType":"guide_topic","number":7,"mustKnow":[{"text":"The three learning outcomes; knowledge (definition, tacit and explicit, the 4 types of entrepreneurial knowledge); entrepreneurial skills (2 definitions, 9 types); the 10 roles of knowledge and skills; digital entrepreneurship and its 5 kinds of digital business; digital technologies and the 6 groups of digital tools; the 6 impacts of digital technology; the virtual office (features, tools, 5 importances); online networking (3 definitions, 5 importances); e-commerce (3 definitions, 6 types, 8 strategies, 10 opportunities)."}],"lessons":[{"number":"7.1","title":"Learning outcomes, knowledge and skills","mustKnow":[{"type":"paragraph","text":[{"text":"This topic (Weeks 12 and 13, Contemporary Issues in Entrepreneurship) has "},{"text":"3 learning outcomes","bold":true},{"text":". By the end you should be able to:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Understand","bold":true},{"text":" the role of knowledge and skills in modern entrepreneurship."}]},{"text":[{"text":"Assess","bold":true},{"text":" the impact of digital technology and "},{"text":"apply","bold":true},{"text":" relevant digital tools for entrepreneurship."}]},{"text":[{"text":"Demonstrate","bold":true},{"text":" basic understanding of e-commerce in business operation, and "},{"text":"apply","bold":true},{"text":" basic e-commerce strategies to entrepreneurship."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Knowledge (in entrepreneurship):","bold":true},{"text":" the "},{"text":"information, understanding and expertise","bold":true},{"text":" that entrepreneurs acquire through "},{"text":"education, training and experience","bold":true},{"text":", which enable them to "},{"text":"identify opportunities, make informed decisions and manage business activities effectively","bold":true},{"text":" (Drucker, 1985; Shane, 2003)."}]}]},{"type":"paragraph","text":[{"text":"Major types of knowledge (2):","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Tacit knowledge","bold":true}],[{"text":"Knowledge embedded in "},{"text":"experience, skills and intuition","bold":true}]],[[{"text":"Explicit knowledge","bold":true}],[{"text":"Knowledge that can be "},{"text":"codified, documented and easily shared","bold":true}]]]},{"type":"paragraph","text":[{"text":"Types of entrepreneurial knowledge (4), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Market knowledge:","bold":true},{"text":" understanding customer needs and competitors."}]},{"text":[{"text":"Financial knowledge:","bold":true},{"text":" budgeting, costing, pricing."}]},{"text":[{"text":"Technical knowledge:","bold":true},{"text":" product or service development."}]},{"text":[{"text":"Legal knowledge:","bold":true},{"text":" business laws and regulations."}]}]},{"type":"paragraph","text":[{"text":"Entrepreneurial skills: 2 definitions","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"practical abilities and competencies","bold":true},{"text":" that enable entrepreneurs to "},{"text":"apply knowledge effectively","bold":true},{"text":" in planning, organising, managing resources and solving problems i$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 28, $study_guide$n order to "},{"text":"create and sustain business ventures","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"capability to perform entrepreneurial tasks effectively","bold":true},{"text":", such as "},{"text":"opportunity recognition, relationship building and strategic decision-making","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Types of skills (9), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Managerial skills:","bold":true},{"text":" involve planning, organising, controlling."}]},{"text":[{"text":"Communication and negotiation."}]},{"text":[{"text":"Problem-solving and decision-making skills."}]},{"text":[{"text":"Digital and technological skills."}]},{"text":[{"text":"Technical skills."}]},{"text":[{"text":"Financial and budgeting skills."}]},{"text":[{"text":"Marketing skills."}]},{"text":[{"text":"Strategic skills."}]},{"text":[{"text":"Personal and creative skills."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Knowledge versus skills.","bold":true},{"text":" Knowledge is information and understanding (what you know); skills are the practical abilities to apply that knowledge (what you can do). Do not swap where knowledge comes from ("},{"text":"education, training and experience","bold":true},{"text":") for look-alike triples such as \"capital, labour and time\" or \"collection, storage and processing\"."}]},{"text":[{"text":"Tacit or explicit?","bold":true},{"text":" A caterer who can tell her jollof rice is ready by its smell after years in the kitchen has "},{"text":"tacit","bold":true},{"text":" knowledge; a bakery's recipe manual that every new staff member reads is "},{"text":"explicit","bold":true},{"text":"."}]},{"text":[{"text":"Matching knowledge types:","bold":true},{"text":" studying the regulations that govern your trade = "},{"text":"legal","bold":true},{"text":"; learning to design a better product = "},{"text":"technical","bold":true},{"text":". \"Managerial knowledge\" is "},{"text":"not","bold":true},{"text":" one of the four (managerial is a "},{"text":"skill","bold":true},{"text":"), and "},{"text":"legal","bold":true},{"text":" is a knowledge type but "},{"text":"not","bold":true},{"text":" a skill type."}]},{"text":[{"text":"Match skill types to behaviour: persuading a supplier to cut the price and give you longer to pay = "},{"text":"communication and negotiation","bold":true},{"text":"; preparing a budget and tracking every naira against it = "},{"text":"financial and budgeting skills","bold":true},{"text":"."}]},{"text":[{"text":"Memory picture: "},{"text":"EXPERTISE","bold":true},{"text":" is built from learning, experience, practice, ego, purpose, talent, ideas, skill and intelligence."}]}]}]},{"number":"7.2","title":"Role of knowledge and skills in entrepreneurship","mustKnow":[{"type":"paragraph","text":[{"text":"There are "},{"text":"10 roles","bold":true},{"text":", shown in two sets of five. In each one, "},{"text":"knowledge","bold":true},{"text":" does one thing and "},{"text":"skills","bold":true},{"text":" do another."}]},{"type":"table","header":[[{"text":"No."}],[{"text":"Role"}],[{"text":"What knowledge does"}],[{"text":"What skills do"}]],"rows":[[[{"text":"1"}],[{"text":"Opportunity recognition","bold":true}],[{"text":"Helps entrepreneurs understand market trends and customers' needs"}],[{"text":"Enable them to analyse information and recognise viable business opportunities"}]],[[{"text":"2"}],[{"text":"Innovation and creativity","bold":true}],[{"text":"Supports research, idea generation and technological adoption"}],[{"text":"Allow entrepreneurs to transform ideas into innovative products and services"}]],[[{"text":"3"}],[{"text":"Efficient resource management","bold":true}],[{"text":"Financial and operational knowledge guide optimal resource allocation"}],[{"text":"Help entrepreneurs manage capital, labour and time effectively"}]],[[{"text":"4"}],[{"text":"Effective business planning","bold":true}],[{"text":"Financial knowledge improves budgeting, costing and pricing decisions"}],[{"text":"Ensure profitability, cash flow management and long-term survival"}]],[[{"text":"5"}],[{"text":"Financial performance and sustainability","bold":true}],[{"text":"Aids in preparing business plans, market analysis and feasibility studies"}],[{"text":"Managerial skills ensure proper planning, organising and control of business activities"}]],[[{"text":"6"}],[{"text":"Adoption of digital technology","bold":true}],[{"text":"Enables understanding of digital tools and platforms"}],[{"text":"Digital skills support e-commerce, online marketing and virtual operations"}]],[[{"text":"7"}],[{"text":"Risk-management and decision making","bold":true}],[{"text":"Improves assessment of business risks and uncertainties"}],[{"text":"Enhance problem-solving and informed decision-making"}]],[[{"text":"8"}],[{"text":"Business growth and competitiveness","bold":true}],[{"text":"Helps entrepreneurs understand competitive strategies and market positioning"}],[{"text":"Enable scaling, customer retention and market expansion"}]],[[{"text":"9"}],[{"text":"Ethical and sustainable entrepreneurship","bold":true}],[{"text":"Knowledge of laws and ethics promotes responsible business conduct"}],[{"text":"Support implementation of sustainable and socially responsible practices"}]],[[{"text":"10"}],[{"text":"Continuous learning and adaptability","bold":true}],[{"text":"Knowledge acquisition supports lifelong planning"}],[{"text":"Enable adaptability to changing business environments and technologies"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Learn each role by its key phrase and picture:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Efficient resource management","bold":true},{"text":" = "},{"text":"capital, labour and time","italic":true},{"text":". A laundry owner in Yaba sharing limited capital, staff hours $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 29, $study_guide$and machine time so nothing is wasted."}]},{"text":[{"text":"Ethical and sustainable entrepreneurship","bold":true},{"text":" = "},{"text":"laws and ethics","italic":true},{"text":", "},{"text":"responsible business conduct","bold":true},{"text":". A recycling start-up that refuses to dump waste illegally because its founders know the environmental laws."}]},{"text":[{"text":"Continuous learning and adaptability","bold":true},{"text":" = adapting to "},{"text":"changing environments and technologies","italic":true},{"text":". A printer who keeps taking short courses and changing how he works as customers move to new technology."}]},{"text":[{"text":"Note the placing: the budgeting, costing and pricing text sits under "},{"text":"effective business planning","bold":true},{"text":"; business plans, market analysis and feasibility studies sit under "},{"text":"financial performance and sustainability","bold":true},{"text":", with "},{"text":"managerial skills","bold":true},{"text":". Learn them exactly as placed."}]}]}]},{"text":[{"text":"Exam trap:","bold":true},{"text":" the \"NOT a role\" question will slip in an item from another list in this topic. These are "},{"text":"not","bold":true},{"text":" roles of knowledge and skills: improved market access and cost reduction (impacts of digital technology), cost efficiency (virtual office importance), resource mobilisation and market visibility and brand building (online networking importances), build trust and credibility (an e-commerce strategy)."}]}]}]},{"number":"7.3","title":"Digital entrepreneurship, digital technologies and digital tools","mustKnow":[{"type":"paragraph","text":[{"text":"Digital entrepreneurship: 3 statements","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The "},{"text":"creation, development and growth of business ventures","bold":true},{"text":" through the use of "},{"text":"digital technologies","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"creation of new ventures","bold":true},{"text":" and the "},{"text":"transformation of existing businesses","bold":true},{"text":" through the development of "},{"text":"novel digital technologies and innovative business models","bold":true},{"text":"."}]},{"text":[{"text":"Digital entrepreneurial activities rely on "},{"text":"digital artifacts, digital platforms and digital infrastructures","bold":true},{"text":" for "},{"text":"value creation and delivery","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Examples of digital businesses (5 kinds):","bold":true}]},{"type":"table","header":[[{"text":"No."}],[{"text":"Kind"}],[{"text":"Examples"}]],"rows":[[[{"text":"1"}],[{"text":"E-commerce businesses","bold":true},{"text":" (online retail stores)"}],[{"text":"Jumia, Konga, Amazon, Slot"}]],[[{"text":"2"}],[{"text":"Digital service businesses","bold":true}],[{"text":"Online education platforms: Coursera, LinkedIn, Udemy. Software as a service: Zoom, Dropbox, Google, Slack"}]],[[{"text":"3"}],[{"text":"Digital media services","bold":true},{"text":" (subscription-based)"}],[{"text":"Streaming services: Netflix, Disney. Podcasting platforms: Spotify, Apple Podcasts, YouTube channels"}]],[[{"text":"4"}],[{"text":"Digital health businesses","bold":true}],[{"text":"Telemedicine platforms, wellness apps, online pharmacy services"}]],[[{"text":"5"}],[{"text":"Digital finance businesses","bold":true}],[{"text":"Online banking and payments, crypto currency exchanges; PayPal, Flutterwave, Paystack, Opay"}]]]},{"type":"paragraph","text":[{"text":"Digital technologies: 2 definitions","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Tools and systems based on digital computing","bold":true},{"text":" that enable the "},{"text":"collection, storage, processing and exchange of information","bold":true},{"text":"."}]},{"text":[{"text":"Platforms and infrastructures","bold":true},{"text":" that enable "},{"text":"new forms of entrepreneurial activity, innovation and value creation","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Examples of digital technologies (7):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Internet and cloud computing"}]},{"text":[{"text":"Computers, smartphones and tablets"}]},{"text":[{"text":"Software applications and mobile apps"}]},{"text":[{"text":"E-commerce platforms"}]},{"text":[{"text":"Social media and digital marketing tools"}]},{"text":[{"text":"Artificial Intelligence (AI) and data analytics"}]},{"text":[{"text":"Financial technologies (FinTech)"}]}]},{"type":"paragraph","text":[{"text":"Relevant digital technology tools for entrepreneurial growth (6 groups):","bold":true}]},{"type":"table","header":[[{"text":"Group"}],[{"text":"Tools"}],[{"text":"What they do"}]],"rows":[[[{"text":"E-commerce platforms","bold":true}],[{"text":"Shopify, Jumia, Temu"}],[{"text":"Enable online selling and digital storefronts"}]],[[{"text":"Digital marketing tools","bold":true}],[{"text":"Social media platforms (Instagram, Facebook, LinkedIn); Google Ads and Search Engine Optimisation (SEO) tools; email marketing platform (Mailchimp)"}],[{"text":"Social media, search advertising and SEO, email marketing"}]],[[{"text":"Financial and accounting tools","bold":true}],[{"text":"Mobile payment systems (Paystack, Flutterwave, PayPal); accounting software (QuickBook, Wave)"}],[{"text":"Mobile payments and accounting software"}]],[[{"text":"Communication and collaboration tools","bold":true}],[{"text":"Zoom, Microsoft Teams, Google Meet; Slack, WhatsApp Business"}],[{"text":"Slack and WhatsApp Business support virtual offices and teamwork"}]],[[{"text":"Data analytics and customer management tools","bold":true}],[{"text":"Google Analytics; Customer Relationship Management (CRM) systems (HubSpot)"}],[{"text":"Support data-driven decision-making"}]],[[{"text":"Productivity and project management tools","bold":true}],[{"text":"Trello, Asana, Notion"}],[{$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 30, $study_guide$"text":"Help manage tasks, time and resources effectively"}]]]},{"type":"paragraph","text":[{"text":"Impact of digital technology on entrepreneurial growth (6), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Improved market access:","bold":true},{"text":" reach local, national and global markets; reduce geographical barriers through online platforms; enhance customer reach and market expansion."}]},{"text":[{"text":"Cost reduction and efficiency:","bold":true},{"text":" lowers operational and transaction costs; reduces need for physical offices and large workforce; improves productivity through automation."}]},{"text":[{"text":"Innovation and new business models:","bold":true},{"text":" supports development of digital products and services; enables platform-based and sharing economy models; encourages creativity and continuous innovation."}]},{"text":[{"text":"Enhance customer engagement:","bold":true},{"text":" enables real-time communication with customers; improves customer feedback and relationship management; supports personalised marketing strategies."}]},{"text":[{"text":"Financial inclusion and access to capital:","bold":true},{"text":" digital finance tools enable online payments and transactions; improve access to loans, crowdfunding and investors; support cash flow management."}]},{"text":[{"text":"Scalability and business growth:","bold":true},{"text":" enables rapid scaling without a proportionate increase in costs; supports remote work and global collaboration; enhances competitiveness and sustainability."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Digital technology","bold":true},{"text":" is the tool; "},{"text":"digital entrepreneurship","bold":true},{"text":" is the business built with it, covering "},{"text":"new","bold":true},{"text":" ventures and the "},{"text":"transformation of existing","bold":true},{"text":" ones."}]},{"text":[{"text":"Traps:","bold":true},{"text":" Netflix is "},{"text":"not","bold":true},{"text":" e-commerce; Spotify is a "},{"text":"podcasting platform","bold":true},{"text":"; Zoom here is "},{"text":"software as a service","bold":true},{"text":"; digital media services are "},{"text":"subscription-based","bold":true},{"text":"; a video-consultation app for patients is "},{"text":"digital health","bold":true},{"text":". Crowdfunding, affiliate marketing and tacit knowledge are "},{"text":"not","bold":true},{"text":" examples of digital technologies."}]},{"text":[{"text":"Same name, different lists:","bold":true},{"text":" Jumia is an e-commerce business and an e-commerce platform; Paystack, Flutterwave and PayPal are digital finance businesses and also "},{"text":"mobile payment systems","bold":true},{"text":"; LinkedIn is an online education platform and a social media platform. Answer by the group the question names. An events planner who wants to assign tasks and track deadlines would pick "},{"text":"Trello","bold":true},{"text":"."}]},{"text":[{"text":"Impacts in practice:","bold":true},{"text":" an Aba shoemaker selling to buyers in Ghana and the UK online without opening shops abroad = "},{"text":"improved market access","bold":true},{"text":"; an agritech founder raising start-up money from hundreds of small backers by crowdfunding = "},{"text":"financial inclusion and access to capital","bold":true},{"text":"."}]},{"text":[{"text":"There are "},{"text":"6","bold":true},{"text":" impacts. \"Professional business presence\" is a virtual office importance, not an impact of digital technology. Both this list and the virtual office list contain \""},{"text":"Scalability and business growth","bold":true},{"text":"\", but with different meanings: here it is scaling without a proportionate rise in costs; for the virtual office it is expanding or downsizing without relocation."}]}]}]},{"number":"7.4","title":"Virtual office and online networking","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Virtual office:","bold":true},{"text":" a business solution that allows organisations and entrepreneurs to "},{"text":"operate remotely","bold":true},{"text":" by providing digital services such as a "},{"text":"business address, communication tools and administrative support","bold":true},{"text":" without the need for a "},{"text":"physical office space","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Key features of a virtual office (5), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Registered business address"}]},{"text":[{"text":"Mail handling and forwarding"}]},{"text":[{"text":"Virtual receptionist / call answering services"}]},{"text":[{"text":"Online meeting tools (Zoom, Microsoft Teams)"}]},{"text":[{"text":"Cloud-based collaboration tools (Google Workspace, Microsoft 365)"}]}]},{"type":"paragraph","text":[{"text":"Virtual office tools (4):","bold":true}]},{"type":"table","header":[[{"text":"Tool"}],[{"text":"Use"}]],"rows":[[[{"text":"Google Workspace"}],[{"text":"Email and document collaboration"}]],[[{"text":"Zoom / Microsoft Teams"}],[{"text":"Virtual meetings"}]],[[{"text":"Slack"}],[{"text":"Team communication"}]],[[{"text":"Regus / WeWork"}],[{"text":"Virtual office address and admin services"}]]]},{"type":"paragraph","text":[{"text":"Importance of virtual office to entrepreneurship (5), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Access to global talents:","bold":true},{"text":" entrepreneurs can recruit skilled professionals remotely, increasing access to diverse and specialised people."}]},{"text":[{"text":"Cost efficiency:","bold":true},{"text":" reduces start-up and operational costs by eliminating expenses related to rent, utilities and physical infrastructure."}]},{"text":[{"text":"Flexible and work life balance:","bold":true},{"text":" entrepreneurs can operate from any location, enabling flexible working arrangem$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 31, $study_guide$ents and improved productivity."}]},{"text":[{"text":"Professional business presence:","bold":true},{"text":" provides a credible business address, mail handling and professional communication services."}]},{"text":[{"text":"Scalability and business growth:","bold":true},{"text":" allows businesses to expand or downsize operations easily without relocation or heavy capital investment."}]}]},{"type":"paragraph","text":[{"text":"Online networking: 3 definitions","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"The use of "},{"text":"internet-based applications","bold":true},{"text":" that enable the "},{"text":"creation and exchange of user-generated content","bold":true},{"text":" and facilitate "},{"text":"interaction among individuals and organisations","bold":true},{"text":"."}]},{"text":[{"text":"Social interaction and relationship building","bold":true},{"text":" through "},{"text":"digitally mediated networks","bold":true},{"text":" that "},{"text":"transcend time and space constraints","bold":true},{"text":"."}]},{"text":[{"text":"The use of "},{"text":"digital platforms and internet tools","bold":true},{"text":" to "},{"text":"create and sustain relationships","bold":true},{"text":" for "},{"text":"professional, social and entrepreneurial purposes","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Importance of online networking to entrepreneurship (5), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Access to business opportunities:","bold":true},{"text":" identify customers, partners, investors and suppliers beyond local boundaries."}]},{"text":[{"text":"Resource mobilisation:","bold":true},{"text":" access to funding opportunities, collaborations and strategic alliances."}]},{"text":[{"text":"Knowledge sharing and learning:","bold":true},{"text":" industry insights, best practices and mentorship through online professional communities."}]},{"text":[{"text":"Innovation and collaboration:","bold":true},{"text":" collaboration, co-creation and idea exchange among entrepreneurs and stakeholders."}]},{"text":[{"text":"Market visibility and brand building:","bold":true},{"text":" social media and professional platforms help entrepreneurs promote their ventures and build brand awareness."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Features versus tools.","bold":true},{"text":" The 5 features are what a virtual office provides (address, mail, receptionist, online meetings, cloud collaboration). The 4 tools are the products used. Zoom and Microsoft Teams are the "},{"text":"online meeting tools","bold":true},{"text":" feature; Google Workspace and Microsoft 365 are the "},{"text":"cloud-based collaboration","bold":true},{"text":" feature. In the tools list, Google Workspace = "},{"text":"email and document collaboration","bold":true},{"text":", Slack = "},{"text":"team communication","bold":true},{"text":", Regus and WeWork = "},{"text":"virtual office address and admin services","bold":true},{"text":". Order tracking and automated notification is an e-commerce strategy, "},{"text":"not","bold":true},{"text":" a virtual office feature."}]},{"text":[{"text":"A Lagos start-up hiring an analyst in Kano and a designer in Nairobi, all working remotely, shows "},{"text":"access to global talents","bold":true},{"text":"."}]},{"text":[{"text":"Online networking","bold":true},{"text":" is relationship building on the internet. The three definitions give you three exam hooks: "},{"text":"user-generated content","bold":true},{"text":"; "},{"text":"transcend time and space constraints","bold":true},{"text":"; "},{"text":"professional, social and entrepreneurial purposes","bold":true},{"text":"."}]},{"text":[{"text":"A fashion entrepreneur who picks up insights and a mentor in an online community shows "},{"text":"knowledge sharing and learning","bold":true},{"text":"; a skincare brand promoting itself on Instagram and LinkedIn shows "},{"text":"market visibility and brand building","bold":true},{"text":"."}]},{"text":[{"text":"Do not mix the two lists of five.","bold":true},{"text":" Virtual office: global talents, cost efficiency, flexibility, professional presence, scalability. Online networking: business opportunities, resource mobilisation, knowledge sharing, innovation and collaboration, market visibility. So \"resource mobilisation\" is "},{"text":"not","bold":true},{"text":" a virtual office importance, and \"cost efficiency\" is "},{"text":"not","bold":true},{"text":" an online networking importance. \"Professional business presence\" (virtual office) and \"market visibility and brand building\" (online networking) sound alike; the first is about a credible address, the second about promotion and brand awareness."}]}]}]},{"number":"7.5","title":"Electronic commerce: types, strategies and opportunities","mustKnow":[{"type":"paragraph","text":[{"text":"E-commerce: 3 definitions","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Electronic commerce (e-commerce):","bold":true},{"text":" the "},{"text":"buying and selling of goods and services","bold":true},{"text":", as well as the "},{"text":"exchange of money and data","bold":true},{"text":", through "},{"text":"electronic networks, primarily the internet","bold":true},{"text":"."}]},{"text":[{"text":"Commercial transactions","bold":true},{"text":" involving the "},{"text":"exchange of value","bold":true},{"text":" conducted over "},{"text":"digital networks","bold":true},{"text":"."}]},{"text":[{"text":"The "},{"text":"sale or purchase","bold":true},{"text":" of goods or services conducted over a "},{"text":"computer network","bold":true},{"text":" by methods "},{"text":"specifically designed for receiving or placing orders","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Points listed with e-commerce in business operation: 24/7 business availability; reduced operational costs; fa$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 32, $study_guide$ster transaction processing; improved record-keeping and data management; enhanced customer convenience and satisfaction."}]},{"type":"paragraph","text":[{"text":"Types of e-commerce (6):","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Examples"}]],"rows":[[[{"text":"Business-to-Consumer (B2C)","bold":true}],[{"text":"Businesses sell products or services directly to individual consumers online"}],[{"text":"Jumia, Amazon, Konga"}]],[[{"text":"Business-to-Business (B2B)","bold":true}],[{"text":"Businesses sell products or services to other businesses through digital platforms"}],[{"text":"Alibaba, software subscription"}]],[[{"text":"Consumer-to-Consumer (C2C)","bold":true}],[{"text":"Individuals sell goods or services directly to other individuals via online marketplaces"}],[{"text":"eBay, Facebook Marketplace, Jiji.ng"}]],[[{"text":"Consumer-to-Business (C2B)","bold":true}],[{"text":"Individuals offer products or services to businesses"}],[{"text":"Freelancer offering services on Upwork; influencers promoting brands"}]],[[{"text":"Business-to-Government (B2G)","bold":true}],[{"text":"Businesses provide goods or services to government agencies through platforms"}],[{"text":"Online procurement portals, e-tendering systems"}]],[[{"text":"Government-to-Consumer (G2C)","bold":true}],[{"text":"Government services delivered electronically to citizens"}],[{"text":"Online tax payment platform, e-visa and passport application system"}]]]},{"type":"paragraph","text":[{"text":"Applying basic e-commerce strategies to entrepreneurship (8), in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Develop an online presence:","bold":true},{"text":" create a website, mobile app or social media store to showcase products and services."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Use platforms like Shopify, Temu, Facebook or Instagram."}]},{"text":[{"text":"Ensure clear product descriptions, pricing and images."}]}]}]},{"text":[{"text":"Choose the right e-commerce model:","bold":true},{"text":" adopt an appropriate model based on your offerings."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"B2C for retail products and B2B for wholesale or services."}]},{"text":[{"text":"C2C for marketplaces and C2B for freelancing and digital services."}]}]}]},{"text":[{"text":"Implement secure online payment system:","bold":true},{"text":" provide multiple and secure payment options."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Integrate Paystack, Flutterwave, PayPal or bank transfers."}]},{"text":[{"text":"Offer mobile money and card payment options."}]}]}]},{"text":[{"text":"Focus on digital marketing strategies:","bold":true},{"text":" e-commerce success depends on "},{"text":"visibility and customer engagement","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Use social media marketing, SEO and email marketing."}]},{"text":[{"text":"Run targeted online advertisements."}]}]}]},{"text":[{"text":"Optimise customer experience:","bold":true},{"text":" user-friendly design improves "},{"text":"customer satisfaction and retention","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Ensure easy navigation and fast-loading websites."}]},{"text":[{"text":"Provide live chat and prompt customer support."}]}]}]},{"text":[{"text":"Manage logistics and order fulfilment:","bold":true},{"text":" efficient delivery systems "},{"text":"build customer trust","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Partner with logistics providers for timely delivery."}]},{"text":[{"text":"Use order tracking and automated notification."}]}]}]},{"text":[{"text":"Use data analytics for decision-making:","bold":true},{"text":" e-commerce platforms provide valuable business insights."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Track customer behaviour, sales trends and conversion rates."}]},{"text":[{"text":"Adjust pricing, promotions and inventory accordingly."}]}]}]},{"text":[{"text":"Build trust and credibility:","bold":true},{"text":" trust is essential in online transactions."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Display customer reviews and ratings."}]},{"text":[{"text":"Use secure checkout systems and transparent return policies."}]}]}]}]},{"type":"paragraph","text":[{"text":"Entrepreneurial opportunities in e-commerce (10):","bold":true}]},{"type":"table","header":[[{"text":"First five"}],[{"text":"Second five"}]],"rows":[[[{"text":"Online retail marketplaces and niche stores"}],[{"text":"AI-enabled e-commerce solutions"}]],[[{"text":"Dropshipping business"}],[{"text":"Sustainable and green e-commerce"}]],[[{"text":"Subscription-based e-commerce"}],[{"text":"Local-to-global export platforms"}]],[[{"text":"Social commerce"}],[{"text":"Digital marketplace for services"}]],[[{"text":"Affiliate marketing"}],[{"text":"Mobile commerce (M-commerce)"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The five points with e-commerce are the gains it brings to a business: the shop never closes (24/7), it costs less to run, payments go through faster, records are kept automatically, and customers enjoy more convenience and satisfaction."}]},{"text":[{"text":"Reading the type codes.","bold":true},{"text":" The first letter is the "},{"text":"seller or provider","bold":true},{"text":", the last letter is the "},{"text":"buyer or receiver","bold":true},{"text":". So B2C is business selling to you; C2B is you (a consumer) offering something to a business. Examples:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A 200-level student selling his used phone to another student on Jiji.ng = "},{"text":"C2C","bold":true},{"text":"."}]},{"text":[{"text":"A freelance gra$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 33, $study_guide$phic designer in Ilorin selling logo designs to companies on Upwork, or an influencer promoting a brand = "},{"text":"C2B","bold":true},{"text":"."}]},{"text":[{"text":"A construction company submitting a bid through a government e-tendering system = "},{"text":"B2G","bold":true},{"text":"."}]},{"text":[{"text":"A citizen paying her personal income tax online, or applying for an e-visa or passport = "},{"text":"G2C","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Traps:","bold":true},{"text":" there are "},{"text":"6","bold":true},{"text":" types. Influencers are "},{"text":"C2B","bold":true},{"text":", not B2C. Facebook Marketplace is "},{"text":"C2C","bold":true},{"text":". B2G runs "},{"text":"from","bold":true},{"text":" business "},{"text":"to","bold":true},{"text":" government (procurement, e-tendering); G2C runs "},{"text":"from","bold":true},{"text":" government "},{"text":"to","bold":true},{"text":" citizens (tax, e-visa, passport). Dropshipping is an "},{"text":"opportunity","bold":true},{"text":", not a type."}]},{"text":[{"text":"Strategies:","bold":true},{"text":" there are "},{"text":"8","bold":true},{"text":", in two sets of four. Model choice: "},{"text":"B2B for wholesale or services","bold":true},{"text":", "},{"text":"C2B for freelancing and digital services","bold":true},{"text":". A bag seller who starts using SEO, email marketing and targeted Instagram adverts is applying "},{"text":"focus on digital marketing strategies","bold":true},{"text":"."}]},{"text":[{"text":"Watch the look-alikes: \"build customer trust\" is the result of "},{"text":"logistics","bold":true},{"text":", while \"build trust and credibility\" is the separate "},{"text":"eighth strategy","bold":true},{"text":". \"Access to global talents\" is a virtual office importance, not a strategy."}]},{"text":[{"text":"Opportunities:","bold":true},{"text":" there are "},{"text":"10","bold":true},{"text":". Picture a dartboard with ten arrows aimed at the bullseye, five from each side. "},{"text":"M-commerce","bold":true},{"text":" means "},{"text":"mobile commerce","bold":true},{"text":". Social commerce, affiliate marketing, dropshipping and subscription-based e-commerce are all opportunities; mail handling, online meeting tools and registered addresses belong to the virtual office, not here."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Knowledge = information, understanding and expertise from education, training and experience (Drucker, 1985; Shane, 2003). Tacit = experience, skills, intuition; explicit = codified, documented, shared."}]},{"text":[{"text":"4 entrepreneurial knowledge types: market, financial, technical, legal. Skills = practical abilities to apply knowledge; 9 types, starting with managerial (planning, organising, controlling)."}]},{"text":[{"text":"10 roles of knowledge and skills, from opportunity recognition to continuous learning and adaptability."}]},{"text":[{"text":"Digital entrepreneurship relies on digital artifacts, platforms and infrastructures; 5 kinds of digital business: e-commerce, digital service, digital media, digital health, digital finance."}]},{"text":[{"text":"Digital technologies collect, store, process and exchange information; tools fall into 6 groups (e-commerce, marketing, financial and accounting, communication, data analytics and CRM, productivity)."}]},{"text":[{"text":"6 impacts: market access, cost reduction, new business models, customer engagement, financial inclusion, scalability."}]},{"text":[{"text":"Virtual office: 5 features, 4 tools, 5 importances (global talents, cost efficiency, flexibility, professional presence, scalability)."}]},{"text":[{"text":"Online networking: 3 definitions, 5 importances (opportunities, resource mobilisation, knowledge sharing, innovation and collaboration, market visibility)."}]},{"text":[{"text":"E-commerce: 6 types (B2C, B2B, C2C, C2B, B2G, G2C), 8 strategies, 10 opportunities."}]}]}],"theory":{"itemId":"9f7175bc-8e36-55f8-a7c5-c77196bd68c9","question":[{"type":"paragraph","text":[{"text":"Define e-commerce and explain any four of its types with an example each."}]}]},"practice":[{"topic":"Weeks 12-13: Contemporary Issues in Entrepreneurship","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"b39817d3-9f40-5d4d-a0f6-4892ed942f71","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"Define entrepreneurship and explain any four of its dimensions with an example each."},"answer":{"kind":"model_answer","itemId":"7f6817e8-2742-5c59-ab82-1afb8981b149","sourceKey":"guide-answer:1","payload":{"body":"Define it as the process of identifying opportunities, mobilising resources, creating innovative products or services and taking risks to generate value and achieve profit. Then, for example: innovativeness (creating or improving; Flutterwave), proactiveness (acting ahead of competitors; Sim Shagaya and Konga), risk taking (calculated risks; Dangote investing despite import dominance), resource mobilisation (gathering and managing resources; Tony Elumelu and UBA)."}}},{"kind":"theory_question","itemId":"93bcc233-d008-5644-a9ad-a5a0ebe330f8","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"Are entrepreneurs born or made? Use the Igba Boi system to support your answer."},"answer":{"kind":"model_answer","itemId":"ba9c94e2-c7c5-56e0-881b-abf2fd8f4e50","sourceKey":"guide-answer:2","payload":{"body":"State the born argument (high energy, natural charisma, high risk tolerance from birth; resilience, creativity, extraversion appear early) and the made argument (skills from education, mentorship and experience; accounting, management, marketing and emotional intelligence are learned). Describe Igba Boi as the world's largest business incubator: young people picked with no capital, nurtured through years of mentorship, then settled (funded). Conclude that its near 100% success rate and the teaching of trade, negotiation and supply chain management prove entrepreneurs ca$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_ent211', 34, $study_guide$n be made."}}},{"kind":"theory_question","itemId":"3e8ac2e5-6278-5151-a752-e50ac292aa30","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"Define innovation and explain its four dimensions, giving one Nigerian example of each."},"answer":{"kind":"model_answer","itemId":"f575a5da-4bd7-5394-88a6-394cf15e30ae","sourceKey":"guide-answer:3","payload":{"body":"Innovation is the systematic practice of developing and marketing breakthrough products and services for adoption by customers (McKinsey, 2022); it is the successful implementation of new ideas that create value, not just invention. Product innovation (improving a product or creating a totally new one): Cowrywise and Piggyvest moving the Kolo to an app with interest. Process innovation (changing how a product is created or delivered to lower cost or increase speed): Chowdeck and Glovo bike delivery within 30 minutes. Market innovation (finding new markets or packaging for existing products): Peak Milk sachets for low-income earners. Organisational innovation (changing workplace culture or structure): Andela's results-based, work-from-home culture."}}},{"kind":"theory_question","itemId":"9a9855b4-670a-571e-943f-42692c7f6c8f","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"List the core components of a simple business plan and state what each one covers."},"answer":{"kind":"model_answer","itemId":"aa144c54-c8b6-5889-8b3a-f3a1d4434678","sourceKey":"guide-answer:4","payload":{"body":"Define a business plan as a strategic roadmap detailing a company's goals and the methods to achieve them (Bank of America, 2025). Then the 8 components, one line each: Executive Summary (summary of the plan), Company Description (what the company does), Business Opportunity (market potential), Competitor Analysis (what makes you stand out), SWOT Analysis (strengths, weaknesses, opportunities, threats), Revenue Model (how you will make money), Financial Projection (growth prediction), Team (how you structure and manage the company)."}}},{"kind":"theory_question","itemId":"a96e4038-68ca-52bd-977d-bce0993a1497","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Outline the steps involved in registering a business in Nigeria."},"answer":{"kind":"model_answer","itemId":"ed9939a4-0984-5705-88be-3222477840d7","sourceKey":"guide-answer:5","payload":{"body":"State that registration is managed by the Corporate Affairs Commission (CAC) under the Companies and Allied Matters Act (CAMA), mainly online through the iCRP Portal, and must be done within 28 days of starting. Then the 4 steps, one line each: choose and reserve a name (with 2 alternatives) on the CAC portal; complete the Pre-Registration Form (CAC-BN01) with business activity and proprietor/partner details (NIN, address, photo); pay the prescribed filing fees online; submit and await approval, then download the electronic Certificate of Registration and Certified Extract. End with the post-registration step: obtain a Tax Identification Number (TIN) from FIRS."}}},{"kind":"theory_question","itemId":"add74835-1e5a-5023-bd76-43e46ad48e9b","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"Using SMEDAN (2017), distinguish between a micro enterprise and a small enterprise, and state two ways micro and small businesses contribute to employment generation."},"answer":{"kind":"model_answer","itemId":"5441fc26-f88a-546c-a696-be963aa415fc","sourceKey":"guide-answer:6","payload":{"body":"Micro: less than 10 employees and total assets (excluding land and building) not exceeding ₦5 million. Small: 10-49 employees and total assets between ₦5 million and ₦49 million, excluding land and buildings. Add one or two contrasts (informal and owner-managed versus formal, semi-formal management). Employment: any two of major source of job creation especially in developing economies; absorb unskilled, semi-skilled and skilled labour; provide jobs for youth, women and vulnerable groups and reduce pressure on the public sector and large firms."}}},{"kind":"theory_question","itemId":"9f7175bc-8e36-55f8-a7c5-c77196bd68c9","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Define e-commerce and explain any four of its types with an example each."},"answer":{"kind":"model_answer","itemId":"15f55bd3-51f1-5981-98f0-0cbf82c14dcb","sourceKey":"guide-answer:7","payload":{"body":"Define e-commerce as the buying and selling of goods and services, and the exchange of money and data, through electronic networks, primarily the internet. Then 1-2 lines each on any four: B2C (business to individual consumers, e.g. Jumia, Konga); B2B (business to business, e.g. Alibaba); C2C (individual to individual, e.g. Jiji.ng, eBay); C2B (individual to business, e.g. a freelancer on Upwork, influencers); B2G (business to government agencies, e.g. e-tendering); G2C (government services to citizens, e.g. online tax payment, e-visa)."}}}]}$study_guide$);
